INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C1','kor',1,1,'u6',1,'글자 하나까지 정확하게 읽기 — 글자 하나를 바꿔 읽으면(타요→가요, 공→곰) 뜻이 달라지거나 통하지 않음을 알고, 짐작하지 않고 글자를 하나하나 살피며 또박또박 읽기',ARRAY['2국02-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C2','kor',1,1,'u6',1,'쉬어 읽는 곳에 따라 달라지는 뜻 — 같은 글자라도 어디서 쉬어 읽느냐에 따라 뜻이 달라짐(오늘 ∨ 밤나무를 / 오늘 밤 ∨ 나무를)을 알고 뜻에 맞는 곳에서 쉬기',ARRAY['2국02-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C3','kor',1,1,'u6',2,'누가·무엇을·어찌하다 문장 — 문장에서 「누가(무엇이)」「무엇을」「어찌하다」를 찾고, 빠진 조각이나 어울리지 않는 말(국수를 마셔요)을 알아채 뜻이 통하는 문장으로 읽고 쓰기',ARRAY['2국02-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C4','kor',1,1,'u6',4,'장면을 떠올리며 그림에 맞는 문장 읽기 — 그림 속 누가, 무엇을, 어떻게 하는지 모두 살펴 알맞은 문장을 고르고, 문장을 읽고 머릿속에 장면을 그려 뜻이 맞는지 스스로 확인하기',ARRAY['2국02-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C5','kor',1,1,'u6',4,'긴 문장을 뜻 덩어리로 쉬어 읽기 — 긴 문장은 뜻이 이어지는 말끼리 묶어 그 사이에서 쉬고, 낱말 가운데서 끊거나 낱말마다 뚝뚝 끊지 않기',ARRAY['2국02-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C6','kor',1,1,'u6',6,'문장 부호의 이름과 쓰임 — 마침표( . )·쉼표( , )·물음표( ? )·느낌표( ! )의 이름을 알고, 설명하는 문장·부르는 말·묻는 문장·느낌을 나타내는 문장에 쓰임을 가리기',ARRAY['2국04-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C7','kor',1,1,'u6',6,'문장에 알맞은 부호 쓰기 — 문장의 뜻에 맞는 끝 부호를 고르고 부르는 말·늘어놓는 말 뒤에 쉼표를 쓰며, 쉼표·마침표는 칸의 왼쪽 아래에 작게 쓰기',ARRAY['2국04-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C8','kor',1,1,'u6',8,'부호에 맞게 쉬어 읽기 표시 — 쉼표 뒤에는 ∨(조금 쉬어), 마침표·물음표·느낌표 뒤에는 ≫(조금 더 쉬어)를 하고 표시대로 쉬어 읽기',ARRAY['2국02-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C9','kor',1,1,'u6',8,'부호를 살려 실감 나게 읽기 — 묻는 문장은 끝을 살짝 올려, 느낌을 나타내는 문장은 느낌을 살려 힘 있게, 설명하는 문장은 끝을 내려 차분하게 읽기',ARRAY['2국02-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u6-C10','kor',1,1,'u6',10,'이야기·대본을 읽고 인물이 되어 읽기 — 이야기와 대본의 내용(누가, 무슨 일, 왜)을 알고, 누가 한 말인지와 인물의 마음을 살펴 목소리 연극으로 실감 나게 읽기',ARRAY['2국05-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X01','kor',1,'u6',ARRAY['K1-1-u6-C1','K1-1-u6-C4']::text[],'아는 낱말이라고 짐작해서 읽어 글자를 바꾸거나 빠뜨리고, 그 때문에 뜻이 달라져도 알아채지 못한다(버스를 타요 → 버스를 가요, 공 → 곰)','손가락으로 글자를 하나씩 짚으며 읽고, 다 읽은 뒤 「뜻이 통하나?」 스스로 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X02','kor',1,'u6',ARRAY['K1-1-u6-C2','K1-1-u6-C5']::text[],'쉬는 곳이 달라도 글자가 같으니 뜻도 같다고 여긴다(오늘 밤 ∨ 나무를 심자 = 오늘 ∨ 밤나무를 심자)','두 가지로 쉬어 읽어 보고 각각 떠오르는 그림을 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X03','kor',1,'u6',ARRAY['K1-1-u6-C2','K1-1-u6-C5','K1-1-u6-C8']::text[],'낱말 한가운데서 끊어 읽는다(할머 ∨ 니께서, 나 ∨ 무를)','낱말에 동그라미를 친 뒤 동그라미 안에서는 쉬지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X04','kor',1,'u6',ARRAY['K1-1-u6-C3']::text[],'문장에서 「누가(무엇이)」와 「무엇을」을 바꿔 찾거나, 「어찌하다」를 「누가」로 고른다','「~이·~가」는 누가, 「~을·~를」은 무엇을 — 끝 글자에 밑줄 긋기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X05','kor',1,'u6',ARRAY['K1-1-u6-C3']::text[],'문장 조각(누가·무엇을·어찌하다)이 빠졌거나 서로 어울리지 않는데(국수를 마셔요, 토끼가 먹어요) 알아채지 못한다','「누가? 무엇을? 어찌하나?」 세 손가락으로 꼽으며 빠진 조각 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X06','kor',1,'u6',ARRAY['K1-1-u6-C4']::text[],'그림의 한 부분(인물만, 물건만)만 보고 문장을 골라 하는 일이나 장소가 그림과 다른 문장을 고른다','그림에서 누가·무엇을·어디서 셋을 먼저 말한 뒤 문장과 하나씩 맞춰 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X07','kor',1,'u6',ARRAY['K1-1-u6-C5']::text[],'긴 문장을 쉬지 않고 한숨에 읽거나, 숨이 찰 때 아무 데서나 또는 낱말마다 뚝뚝 끊어 읽는다','뜻이 이어지는 말끼리 괄호로 묶고 괄호 사이에서만 쉬기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X08','kor',1,'u6',ARRAY['K1-1-u6-C6']::text[],'문장 부호의 이름과 쓰임을 헷갈린다(쉼표 ↔ 마침표, 물음표 ↔ 느낌표)','부호 카드 네 장을 들고 이름과 쓰임을 한 번씩 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X09','kor',1,'u6',ARRAY['K1-1-u6-C6','K1-1-u6-C7']::text[],'문장의 뜻과 다른 끝 부호를 쓴다(묻는 문장에 마침표, 느낌을 나타내는 문장에 물음표)','문장을 읽고 「묻나? 느낌인가? 설명인가?」 먼저 정한 뒤 부호 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X10','kor',1,'u6',ARRAY['K1-1-u6-C7']::text[],'부르는 말이나 늘어놓는 말 뒤에 쉼표를 빼거나 마침표·물음표를 쓴다(할머니. 나무를…)','누구를 부르는 말인지 찾아 손뼉 한 번 — 그 자리에 쉼표') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X11','kor',1,'u6',ARRAY['K1-1-u6-C8']::text[],'쉼표 뒤(∨ 조금 쉬어)와 마침표·물음표·느낌표 뒤(≫ 조금 더 쉬어)의 쉬는 길이를 바꾸거나 모두 같게 한다','쉼표에서 손가락 하나, 끝 부호에서 손가락 둘을 세며 쉬어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X12','kor',1,'u6',ARRAY['K1-1-u6-C9']::text[],'문장 부호를 살리지 않고 모든 문장을 같은 목소리로 밋밋하게 읽는다(느낌표에도 느낌 없음)','느낌표 문장을 「작게 → 크게」 두 번 읽어 보고 더 실감 나는 쪽 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X13','kor',1,'u6',ARRAY['K1-1-u6-C9']::text[],'묻는 문장의 끝을 내려 읽거나, 설명하는 문장의 끝을 올려 묻듯이 읽는다','물음표를 보면 손을 위로, 마침표를 보면 손을 아래로 움직이며 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X14','kor',1,'u6',ARRAY['K1-1-u6-C10']::text[],'이야기·대본을 끝까지 살피지 않아 나오지 않은 일이나 인물, 장소를 말한다','「누가? 어디서? 무슨 일?」을 글에서 찾아 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X15','kor',1,'u6',ARRAY['K1-1-u6-C10']::text[],'대본에서 누가 한 말인지, 인물의 마음이 어떤지 살피지 않고 대사를 읽거나 차례를 지키지 않는다','대사 앞의 인물 이름에 동그라미 — 그 인물의 얼굴을 떠올리며 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u6-X16','kor',1,'u6',ARRAY['K1-1-u6-C7']::text[],'쉼표·마침표를 칸 한가운데나 위쪽에 크게 써서 글자와 헷갈리게 쓴다','칸을 네 칸으로 나눠 보고 왼쪽 아래 칸에만 작게 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#1','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C1',1,'mc','auto','그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X01']::text[],true,'{"seq":1,"concept":"K1-1-u6-C1","difficulty":1,"kind":"mc","stem":"그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"자전거를 타요.","correct":true},{"t":"자전거를 가요.","mis":"K1-1-u6-X01"},{"t":"자전거를 자요.","mis":"K1-1-u6-X01"}],"explanation":["그림 속 아이는 자전거를 타고 있어요.","「타요」를 「가요」·「자요」로 바꿔 읽으면 뜻이 통하지 않아요.","글자 하나까지 살피며 또박또박 읽어요."],"asset":{"type":"scene","icon":"🚲🧒"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"공을 차요.","correct":true},{"t":"곰을 차요.","mis":"K1-1-u6-X01"},{"t":"공을 자요.","mis":"K1-1-u6-X01"}],"explanation":["그림 속 아이는 공을 차고 있어요.","「공」을 「곰」으로, 「차요」를 「자요」로 읽으면 뜻이 달라져요.","글자 하나까지 살피며 또박또박 읽어요."],"asset":{"type":"scene","icon":"⚽🧒"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#2','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C1',1,'ox','auto','「공을 던져요.」를 「곰을 던져요.」로 읽어도 뜻은 같아요.',ARRAY['K1-1-u6-X01']::text[],true,'{"seq":2,"concept":"K1-1-u6-C1","difficulty":1,"kind":"ox","stem":"「공을 던져요.」를 「곰을 던져요.」로 읽어도 뜻은 같아요.","answer":"X","reason_options":[{"t":"「공」과 「곰」은 글자 하나 차이지만 뜻이 전혀 다르니까","correct":true},{"t":"글자 하나쯤은 바꿔 읽어도 괜찮으니까","mis":"K1-1-u6-X01"}],"mis":"K1-1-u6-X01","explanation":["「공」과 「곰」은 다른 낱말이에요.","글자 하나만 바꿔 읽어도 뜻이 달라져요.","글자를 하나씩 짚으며 읽어요."],"variant_rule":{"alt":[{"stem":"「빵을 사요.」를 「방을 사요.」로 읽어도 뜻은 같아요.","answer":"X","reason_options":[{"t":"「빵」과 「방」은 글자 하나 차이지만 뜻이 다르니까","correct":true},{"t":"소리가 비슷하면 뜻도 같으니까","mis":"K1-1-u6-X01"}],"explanation":["「빵」과 「방」은 다른 낱말이에요.","글자 하나 차이로 뜻이 달라져요.","글자를 하나씩 짚으며 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#3','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C2',1,'mc','auto','밤이 열리는 나무를 심는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X02','K1-1-u6-X03']::text[],true,'{"seq":3,"concept":"K1-1-u6-C2","difficulty":1,"kind":"mc","stem":"밤이 열리는 나무를 심는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"오늘 ∨ 밤나무를 심자","correct":true},{"t":"오늘 밤 ∨ 나무를 심자","mis":"K1-1-u6-X02"},{"t":"오늘 밤나 ∨ 무를 심자","mis":"K1-1-u6-X03"}],"explanation":["밤이 열리는 나무를 심으니 「밤나무」를 붙여 읽어요.","「오늘 밤 ∨ 나무를」로 읽으면 깜깜한 밤에 나무를 심는다는 뜻이 돼요.","뜻을 떠올리고 그 뜻에 맞는 곳에서 쉬어요."],"asset":{"type":"scene","icon":"🌰🌳"},"variant_rule":{"alt":[{"stem":"깜깜한 밤에 나무를 심는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"오늘 밤 ∨ 나무를 심자","correct":true},{"t":"오늘 ∨ 밤나무를 심자","mis":"K1-1-u6-X02"},{"t":"오늘 밤 ∨ 나 ∨ 무를 심자","mis":"K1-1-u6-X03"}],"explanation":["밤에 나무를 심으니 「오늘 밤」 뒤에서 쉬어요.","「밤나무를」로 붙이면 밤이 열리는 나무라는 뜻이 돼요.","뜻을 떠올리고 그 뜻에 맞는 곳에서 쉬어요."],"asset":{"type":"scene","icon":"🌙🌲"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#4','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C2',1,'mc','auto','아버지가 방으로 들어가시는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X02','K1-1-u6-X03']::text[],true,'{"seq":4,"concept":"K1-1-u6-C2","difficulty":1,"kind":"mc","stem":"아버지가 방으로 들어가시는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"아버지가 ∨ 방에 들어가신다","correct":true},{"t":"아버지 ∨ 가방에 들어가신다","mis":"K1-1-u6-X02"},{"t":"아 ∨ 버지가 방에 들어가신다","mis":"K1-1-u6-X03"}],"explanation":["아버지가 방에 들어가시니 「아버지가」 뒤에서 쉬어요.","「아버지 ∨ 가방에」로 읽으면 가방 속으로 들어간다는 우스운 뜻이 돼요.","낱말을 바르게 묶어 그 사이에서 쉬어요."],"asset":{"type":"scene","icon":"👨🚪"},"variant_rule":{"alt":[{"stem":"누나가 방을 청소하는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"누나가 ∨ 방을 치워요","correct":true},{"t":"누나 ∨ 가방을 치워요","mis":"K1-1-u6-X02"},{"t":"누 ∨ 나가 방을 치워요","mis":"K1-1-u6-X03"}],"explanation":["누나가 방을 치우니 「누나가」 뒤에서 쉬어요.","「누나 ∨ 가방을」로 읽으면 누나의 가방을 치운다는 뜻이 돼요.","낱말을 바르게 묶어 그 사이에서 쉬어요."],"asset":{"type":"scene","icon":"🧹🛏️"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#5','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C1',2,'mc','auto','「버스를 타요.」를 「버스를 가요.」로 읽으면 어떻게 되나요?',ARRAY['K1-1-u6-X01']::text[],true,'{"seq":5,"concept":"K1-1-u6-C1","difficulty":2,"kind":"mc","stem":"「버스를 타요.」를 「버스를 가요.」로 읽으면 어떻게 되나요?","options":[{"t":"뜻이 통하지 않는 문장이 돼요","correct":true},{"t":"뜻이 똑같아요","mis":"K1-1-u6-X01"},{"t":"더 또박또박 읽은 거예요","mis":"K1-1-u6-X01"}],"explanation":["「타요」를 「가요」로 바꾸면 뜻이 통하지 않아요.","글자 하나가 달라도 뜻은 크게 달라져요.","다 읽은 뒤 「뜻이 통하나?」 스스로 물어요."],"variant_rule":{"alt":[{"stem":"「물을 마셔요.」를 「불을 마셔요.」로 읽으면 어떻게 되나요?","options":[{"t":"뜻이 통하지 않는 문장이 돼요","correct":true},{"t":"뜻이 똑같아요","mis":"K1-1-u6-X01"},{"t":"더 실감 나게 읽은 거예요","mis":"K1-1-u6-X01"}],"explanation":["「물」을 「불」로 바꾸면 뜻이 통하지 않아요.","글자 하나가 달라도 뜻은 크게 달라져요.","다 읽은 뒤 「뜻이 통하나?」 스스로 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#6','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C2',2,'match','auto','쉬어 읽은 문장과 그 뜻을 이으세요.','{}'::text[],true,'{"seq":6,"concept":"K1-1-u6-C2","difficulty":2,"kind":"match","stem":"쉬어 읽은 문장과 그 뜻을 이으세요.","pairs":[{"l":"오늘 ∨ 밤나무를 심자","r":"밤이 열리는 나무를 심어요"},{"l":"오늘 밤 ∨ 나무를 심자","r":"깜깜한 밤에 나무를 심어요"},{"l":"나 ∨ 물 좀 주세요","r":"마실 물을 달라고 해요"}],"mis":"K1-1-u6-X02","explanation":["「밤나무」로 붙이면 나무 이름, 「오늘 밤」으로 묶으면 때예요.","「나 ∨ 물」은 마실 물을 달라는 뜻이에요.","쉬는 곳을 바꿔 읽고 뜻을 견주어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 쉬어 읽은 문장과 그 뜻을 이으세요.","pairs":[{"l":"나물 ∨ 좀 주세요","r":"반찬 나물을 달라고 해요"},{"l":"나 ∨ 물 좀 주세요","r":"마실 물을 달라고 해요"},{"l":"누나 ∨ 가방을 치워요","r":"누나의 가방을 치워요"}],"explanation":["「나물」로 붙이면 반찬, 「나 ∨ 물」로 쉬면 마실 물이에요.","「누나 ∨ 가방을」은 누나의 가방을 치운다는 뜻이에요.","쉬는 곳을 바꿔 읽고 뜻을 견주어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#7','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C1',2,'mc','auto','국수를 먹는 그림이에요. 그림에 알맞게 읽은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X01']::text[],true,'{"seq":7,"concept":"K1-1-u6-C1","difficulty":2,"kind":"mc","stem":"국수를 먹는 그림이에요. 그림에 알맞게 읽은 문장은 어느 것인가요?","options":[{"t":"동생이 국수를 먹어요.","correct":true},{"t":"동생이 국자를 먹어요.","mis":"K1-1-u6-X01"},{"t":"동생이 국수를 먹여요.","mis":"K1-1-u6-X01"}],"explanation":["동생이 국수를 먹고 있어요.","「국자」·「먹여요」로 읽으면 그림과 뜻이 달라져요.","글자 하나까지 살피며 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"🍜🧒"},"variant_rule":{"alt":[{"stem":"곰이 꿀을 먹는 그림이에요. 그림에 알맞게 읽은 문장은 어느 것인가요?","options":[{"t":"곰이 꿀을 먹어요.","correct":true},{"t":"공이 꿀을 먹어요.","mis":"K1-1-u6-X01"},{"t":"곰이 꿈을 먹어요.","mis":"K1-1-u6-X01"}],"explanation":["곰이 꿀을 먹고 있어요.","「공」·「꿈」으로 읽으면 그림과 뜻이 달라져요.","글자 하나까지 살피며 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"🐻🍯"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#8','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C2',2,'ox','auto','같은 글자로 된 문장이라도 어디서 쉬어 읽느냐에 따라 뜻이 달라질 수 있어요.',ARRAY['K1-1-u6-X02']::text[],false,'{"seq":8,"concept":"K1-1-u6-C2","difficulty":2,"kind":"ox","stem":"같은 글자로 된 문장이라도 어디서 쉬어 읽느냐에 따라 뜻이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"「밤나무」와 「밤 ∨ 나무」처럼 쉬는 곳에 따라 뜻이 바뀌니까","correct":true},{"t":"글자가 같으면 뜻도 언제나 같으니까","mis":"K1-1-u6-X02"}],"mis":"K1-1-u6-X02","explanation":["쉬는 곳이 달라지면 뜻이 달라질 수 있어요.","「오늘 밤 ∨ 나무를」과 「오늘 ∨ 밤나무를」은 뜻이 달라요.","뜻에 맞는 곳에서 쉬어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#9','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C1',2,'mc','auto','정확하게 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X01']::text[],true,'{"seq":9,"concept":"K1-1-u6-C1","difficulty":2,"kind":"mc","stem":"정확하게 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"글자를 하나하나 살피며 또박또박 읽어요","correct":true},{"t":"아는 낱말이면 짐작해서 빨리 읽어요","mis":"K1-1-u6-X01"},{"t":"어려운 글자는 건너뛰고 읽어요","mis":"K1-1-u6-X01"}],"explanation":["글자를 하나하나 살펴야 정확하게 읽을 수 있어요.","짐작하거나 건너뛰면 뜻이 달라질 수 있어요.","손가락으로 짚으며 읽어 봐요."],"variant_rule":{"alt":[{"stem":"글을 정확하게 읽지 않으면 어떤 일이 생길 수 있나요?","options":[{"t":"듣는 사람이 뜻을 잘못 알 수 있어요","correct":true},{"t":"글이 더 재미있어져요","mis":"K1-1-u6-X01"},{"t":"아무 일도 생기지 않아요","mis":"K1-1-u6-X01"}],"explanation":["잘못 읽으면 듣는 사람이 뜻을 잘못 알아요.","재미있어지거나 괜찮은 것이 아니에요.","그래서 또박또박 정확하게 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_basic#10','kor',1,1,'u6','L01','g1_1_kor_u6_L01_basic','lesson_basic','K1-1-u6-C2',3,'error','auto','하린이가 목이 말라 「나 물 좀 줄래?」라고 말하려다 이렇게 읽었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#1','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C1',2,'mc','auto','이를 닦는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X01']::text[],true,'{"seq":1,"concept":"K1-1-u6-C1","difficulty":2,"kind":"mc","stem":"이를 닦는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"이를 닦아요.","correct":true},{"t":"이를 달아요.","mis":"K1-1-u6-X01"},{"t":"이를 닫아요.","mis":"K1-1-u6-X01"}],"explanation":["칫솔로 이를 닦고 있어요.","「달아요」·「닫아요」로 읽으면 뜻이 달라져요.","받침까지 살피며 읽어요."],"asset":{"type":"scene","icon":"🪥🦷"},"variant_rule":{"alt":[{"stem":"문을 여는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"문을 열어요.","correct":true},{"t":"물을 열어요.","mis":"K1-1-u6-X01"},{"t":"문을 얼어요.","mis":"K1-1-u6-X01"}],"explanation":["손으로 문을 열고 있어요.","「물」·「얼어요」로 읽으면 뜻이 통하지 않아요.","받침까지 살피며 읽어요."],"asset":{"type":"scene","icon":"🚪🧒"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#2','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C2',2,'mc','auto','아기가 방으로 기어가는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X02','K1-1-u6-X03']::text[],false,'{"seq":2,"concept":"K1-1-u6-C2","difficulty":2,"kind":"mc","stem":"아기가 방으로 기어가는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"아기가 ∨ 방에 들어가요","correct":true},{"t":"아기 ∨ 가방에 들어가요","mis":"K1-1-u6-X02"},{"t":"아기가방 ∨ 에 들어가요","mis":"K1-1-u6-X03"}],"explanation":["아기가 방에 들어가니 「아기가」 뒤에서 쉬어요.","「아기 ∨ 가방에」로 읽으면 가방 속으로 들어간다는 뜻이 돼요.","뜻에 맞게 낱말을 묶어요."],"asset":{"type":"scene","icon":"👶🚪"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#3','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C1',3,'mc','auto','아빠가 낚시하는 그림이에요. 그림에 맞게 정확히 읽은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X01']::text[],false,'{"seq":3,"concept":"K1-1-u6-C1","difficulty":3,"kind":"mc","stem":"아빠가 낚시하는 그림이에요. 그림에 맞게 정확히 읽은 문장은 어느 것인가요?","options":[{"t":"아빠가 낚싯대로 물고기를 잡아요.","correct":true},{"t":"아빠가 낚싯대로 불고기를 잡아요.","mis":"K1-1-u6-X01"},{"t":"아빠가 낚싯대로 물고기를 감아요.","mis":"K1-1-u6-X01"}],"explanation":["아빠는 물고기를 잡고 있어요.","「불고기」·「감아요」로 읽으면 그림과 뜻이 달라요.","긴 문장도 끝까지 글자 하나하나 살펴요."],"asset":{"type":"scene","icon":"🎣🐟"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#4','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C2',3,'mc','auto','「오늘 ∨ 밤나무를 심자」와 「오늘 밤 ∨ 나무를 심자」의 뜻이 다른 까닭은 무엇인가요?',ARRAY['K1-1-u6-X02']::text[],false,'{"seq":4,"concept":"K1-1-u6-C2","difficulty":3,"kind":"mc","stem":"「오늘 ∨ 밤나무를 심자」와 「오늘 밤 ∨ 나무를 심자」의 뜻이 다른 까닭은 무엇인가요?","options":[{"t":"쉬어 읽는 곳이 달라서","correct":true},{"t":"글자가 서로 달라서","mis":"K1-1-u6-X02"},{"t":"한 문장이 더 길어서","mis":"K1-1-u6-X02"}],"explanation":["두 문장은 글자가 똑같고 쉬는 곳만 달라요.","글자나 길이가 다른 것이 아니에요.","쉬는 곳이 뜻을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#5','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C2',3,'mc','auto','반찬 나물을 달라고 할 때 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X02','K1-1-u6-X03']::text[],false,'{"seq":5,"concept":"K1-1-u6-C2","difficulty":3,"kind":"mc","stem":"반찬 나물을 달라고 할 때 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"나물 ∨ 좀 주세요","correct":true},{"t":"나 ∨ 물 좀 주세요","mis":"K1-1-u6-X02"},{"t":"나물 좀 주 ∨ 세요","mis":"K1-1-u6-X03"}],"explanation":["반찬을 달라니 「나물」을 붙여 읽어요.","「나 ∨ 물」은 마실 물이고, 「주 ∨ 세요」는 낱말 가운데서 끊었어요.","하고 싶은 뜻에 맞게 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#6','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C1',3,'error','auto','시우가 「강아지가 공을 물어요.」를 이렇게 읽었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#7','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C1',3,'ox','auto','짐작해서 빨리 읽으면 글자 하나를 바꿔 읽어도 뜻은 언제나 통해요.',ARRAY['K1-1-u6-X01']::text[],false,'{"seq":7,"concept":"K1-1-u6-C1","difficulty":3,"kind":"ox","stem":"짐작해서 빨리 읽으면 글자 하나를 바꿔 읽어도 뜻은 언제나 통해요.","answer":"X","reason_options":[{"t":"글자 하나만 바뀌어도 뜻이 달라지거나 통하지 않으니까","correct":true},{"t":"빨리 읽는 것이 가장 정확하니까","mis":"K1-1-u6-X01"}],"mis":"K1-1-u6-X01","explanation":["짐작해서 읽으면 글자를 바꿔 읽기 쉬워요.","글자 하나로도 뜻이 달라져요.","빠르기보다 정확하게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#8','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C2',4,'mc','auto','아빠의 가방 안을 정리하는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X02','K1-1-u6-X03']::text[],false,'{"seq":8,"concept":"K1-1-u6-C2","difficulty":4,"kind":"mc","stem":"아빠의 가방 안을 정리하는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"아빠 ∨ 가방을 정리해요","correct":true},{"t":"아빠가 ∨ 방을 정리해요","mis":"K1-1-u6-X02"},{"t":"아 ∨ 빠가방을 정리해요","mis":"K1-1-u6-X03"}],"explanation":["아빠의 가방을 정리하니 「아빠 ∨ 가방을」로 읽어요.","「아빠가 ∨ 방을」로 읽으면 방을 정리한다는 뜻이 돼요.","그림을 보고 뜻에 맞게 쉬어요."],"asset":{"type":"scene","icon":"🎒👨"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#9','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C1',4,'essay','teacher','글자 하나를 잘못 읽어 뜻이 달라지는 예를 하나 들고, 왜 정확하게 읽어야 하는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u6-C1","difficulty":4,"kind":"essay","stem":"글자 하나를 잘못 읽어 뜻이 달라지는 예를 하나 들고, 왜 정확하게 읽어야 하는지 써 보세요.","answer_guide":{"answer":"예: 「공을 차요」를 「곰을 차요」로 읽으면 뜻이 달라져요. 정확하게 읽어야 듣는 사람이 뜻을 바르게 알 수 있어요.","scoring_points":["글자 하나가 바뀐 예를 들었는가","뜻이 어떻게 달라지는지 말했는가","정확하게 읽어야 하는 까닭을 썼는가"]},"explanation":["글자 하나 바뀐 예.","달라진 뜻.","정확하게 읽는 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L01_challenge#10','kor',1,1,'u6','L01','g1_1_kor_u6_L01_challenge','lesson_challenge','K1-1-u6-C2',4,'essay','teacher','「오늘 밤 나무를 심자」를 두 가지로 쉬어 읽고, 뜻이 어떻게 다른지 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u6-C2","difficulty":4,"kind":"essay","stem":"「오늘 밤 나무를 심자」를 두 가지로 쉬어 읽고, 뜻이 어떻게 다른지 말해 보세요.","answer_guide":{"answer":"「오늘 ∨ 밤나무를 심자」는 밤이 열리는 나무를 심자는 뜻, 「오늘 밤 ∨ 나무를 심자」는 깜깜한 밤에 나무를 심자는 뜻이에요.","scoring_points":["두 가지로 쉬어 읽었는가","두 뜻을 각각 바르게 말했는가","쉬는 곳에 따라 뜻이 달라짐을 말했는가"]},"explanation":["두 가지 쉬어 읽기.","두 뜻.","쉬는 곳과 뜻."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#1','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C3',1,'mc','auto','「강아지가 마당에서 뛰어가요.」에서 「누가」에 해당하는 말은 어느 것인가요?',ARRAY['K1-1-u6-X04']::text[],true,'{"seq":1,"concept":"K1-1-u6-C3","difficulty":1,"kind":"mc","stem":"「강아지가 마당에서 뛰어가요.」에서 「누가」에 해당하는 말은 어느 것인가요?","options":[{"t":"강아지가","correct":true},{"t":"마당에서","mis":"K1-1-u6-X04"},{"t":"뛰어가요","mis":"K1-1-u6-X04"}],"explanation":["뛰어가는 것은 강아지예요.","「마당에서」는 곳, 「뛰어가요」는 하는 일이에요.","「~이·~가」로 끝나는 말을 찾아요."],"variant_rule":{"alt":[{"stem":"「아기가 침대에서 웃어요.」에서 「누가」에 해당하는 말은 어느 것인가요?","options":[{"t":"아기가","correct":true},{"t":"침대에서","mis":"K1-1-u6-X04"},{"t":"웃어요","mis":"K1-1-u6-X04"}],"explanation":["웃는 것은 아기예요.","「침대에서」는 곳, 「웃어요」는 하는 일이에요.","「~이·~가」로 끝나는 말을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#2','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C3',1,'mc','auto','「동생이 국수를 먹어요.」에서 「무엇을」에 해당하는 말은 어느 것인가요?',ARRAY['K1-1-u6-X04']::text[],true,'{"seq":2,"concept":"K1-1-u6-C3","difficulty":1,"kind":"mc","stem":"「동생이 국수를 먹어요.」에서 「무엇을」에 해당하는 말은 어느 것인가요?","options":[{"t":"국수를","correct":true},{"t":"동생이","mis":"K1-1-u6-X04"},{"t":"먹어요","mis":"K1-1-u6-X04"}],"explanation":["동생이 먹는 것은 국수예요.","「동생이」는 누가, 「먹어요」는 어찌하다예요.","「~을·~를」로 끝나는 말을 찾아요."],"variant_rule":{"alt":[{"stem":"「누나가 공을 던져요.」에서 「무엇을」에 해당하는 말은 어느 것인가요?","options":[{"t":"공을","correct":true},{"t":"누나가","mis":"K1-1-u6-X04"},{"t":"던져요","mis":"K1-1-u6-X04"}],"explanation":["누나가 던지는 것은 공이에요.","「누나가」는 누가, 「던져요」는 어찌하다예요.","「~을·~를」로 끝나는 말을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#3','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C4',1,'mc','auto','그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],true,'{"seq":3,"concept":"K1-1-u6-C4","difficulty":1,"kind":"mc","stem":"그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"아기가 웃어요.","correct":true},{"t":"아기가 울어요.","mis":"K1-1-u6-X06"},{"t":"아기가 자요.","mis":"K1-1-u6-X06"}],"explanation":["그림 속 아기는 활짝 웃고 있어요.","울거나 자는 모습이 아니에요.","그림 속 얼굴과 몸짓을 살펴요."],"asset":{"type":"scene","icon":"👶😄"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"새가 날아요.","correct":true},{"t":"새가 헤엄쳐요.","mis":"K1-1-u6-X06"},{"t":"물고기가 날아요.","mis":"K1-1-u6-X06"}],"explanation":["그림 속 새가 하늘을 날고 있어요.","헤엄치는 것도, 물고기도 그림에 없어요.","누가, 어떻게 하는지 함께 살펴요."],"asset":{"type":"scene","icon":"🐦☁️"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#4','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C4',1,'blank','auto','얼음이 녹는 그림이에요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#5','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C4',2,'match','auto','그림과 알맞은 문장을 이으세요.','{}'::text[],true,'{"seq":5,"concept":"K1-1-u6-C4","difficulty":2,"kind":"match","stem":"그림과 알맞은 문장을 이으세요.","pairs":[{"l":"🏊","r":"누나가 수영을 해요."},{"l":"🤸","r":"친구들이 줄넘기를 해요."},{"l":"🍜","r":"동생이 국수를 먹어요."}],"mis":"K1-1-u6-X06","explanation":["수영, 줄넘기, 국수 — 그림마다 하는 일이 달라요.","그림의 하는 일과 문장의 하는 일을 맞춰요.","그림을 먼저 말로 해 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림과 알맞은 문장을 이으세요.","pairs":[{"l":"🐶","r":"강아지가 뛰어가요."},{"l":"👶","r":"아기가 웃어요."},{"l":"🐦","r":"새가 날아요."}],"explanation":["강아지는 뛰고, 아기는 웃고, 새는 날아요.","그림의 누가와 하는 일을 함께 맞춰요.","그림을 먼저 말로 해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#6','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C3',2,'mc','auto','「누가 + 무엇을 + 어찌하다」로 된 문장은 어느 것인가요?',ARRAY['K1-1-u6-X05']::text[],true,'{"seq":6,"concept":"K1-1-u6-C3","difficulty":2,"kind":"mc","stem":"「누가 + 무엇을 + 어찌하다」로 된 문장은 어느 것인가요?","options":[{"t":"형이 책을 읽어요.","correct":true},{"t":"형이 웃어요.","mis":"K1-1-u6-X05"},{"t":"책을 읽어요.","mis":"K1-1-u6-X05"}],"explanation":["「형이(누가) 책을(무엇을) 읽어요(어찌하다)」예요.","「형이 웃어요」는 무엇을이 없고, 「책을 읽어요」는 누가가 없어요.","세 손가락으로 조각을 꼽아 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「누가 + 무엇을 + 어찌하다」로 된 문장은 어느 것인가요?","options":[{"t":"동생이 그림을 그려요.","correct":true},{"t":"동생이 자요.","mis":"K1-1-u6-X05"},{"t":"그림을 그려요.","mis":"K1-1-u6-X05"}],"explanation":["「동생이 그림을 그려요」에 세 조각이 다 있어요.","다른 두 문장은 한 조각씩 빠졌어요.","세 손가락으로 조각을 꼽아 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#7','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C3',2,'ox','auto','「토끼가 먹어요.」만으로는 토끼가 무엇을 먹는지 알 수 없어요.',ARRAY['K1-1-u6-X05']::text[],false,'{"seq":7,"concept":"K1-1-u6-C3","difficulty":2,"kind":"ox","stem":"「토끼가 먹어요.」만으로는 토끼가 무엇을 먹는지 알 수 없어요.","answer":"O","reason_options":[{"t":"「무엇을」이 빠져서 무엇을 먹는지 모르니까","correct":true},{"t":"「누가」만 있으면 뜻을 다 알 수 있으니까","mis":"K1-1-u6-X05"}],"mis":"K1-1-u6-X05","explanation":["「무엇을」이 없어 무엇을 먹는지 몰라요.","「토끼가 당근을 먹어요」처럼 쓰면 자세해져요.","빠진 조각이 있는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#8','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C3',2,'mc','auto','「무엇을」과 「어찌하다」가 어울리지 않는 문장은 어느 것인가요?',ARRAY['K1-1-u6-X05']::text[],true,'{"seq":8,"concept":"K1-1-u6-C3","difficulty":2,"kind":"mc","stem":"「무엇을」과 「어찌하다」가 어울리지 않는 문장은 어느 것인가요?","options":[{"t":"누나가 빵을 마셔요.","correct":true},{"t":"누나가 우유를 마셔요.","mis":"K1-1-u6-X05"},{"t":"누나가 빵을 먹어요.","mis":"K1-1-u6-X05"}],"explanation":["빵은 먹는 것이라 「마셔요」와 어울리지 않아요.","우유는 마시고, 빵은 먹어요.","무엇을과 어찌하다를 이어 말해 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「무엇을」과 「어찌하다」가 어울리지 않는 문장은 어느 것인가요?","options":[{"t":"형이 노래를 먹어요.","correct":true},{"t":"형이 노래를 불러요.","mis":"K1-1-u6-X05"},{"t":"형이 밥을 먹어요.","mis":"K1-1-u6-X05"}],"explanation":["노래는 부르는 것이라 「먹어요」와 어울리지 않아요.","노래는 부르고, 밥은 먹어요.","무엇을과 어찌하다를 이어 말해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#9','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C4',2,'mc','auto','수영을 하는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":9,"concept":"K1-1-u6-C4","difficulty":2,"kind":"mc","stem":"수영을 하는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"누나가 수영을 해요.","correct":true},{"t":"누나가 축구를 해요.","mis":"K1-1-u6-X06"},{"t":"누나가 수박을 먹어요.","mis":"K1-1-u6-X06"}],"explanation":["그림 속 누나는 물에서 수영하고 있어요.","축구나 수박은 그림에 없어요.","그림 속 하는 일을 살펴요."],"asset":{"type":"scene","icon":"🏊‍♀️🌊"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_basic#10','kor',1,1,'u6','L02','g1_1_kor_u6_L02_basic','lesson_basic','K1-1-u6-C4',3,'error','auto','고양이가 눈을 감고 누워 있는 그림을 보고 이렇게 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_challenge#1','kor',1,1,'u6','L02','g1_1_kor_u6_L02_challenge','lesson_challenge','K1-1-u6-C3',2,'mc','auto','「꽃이 활짝 피었어요.」에서 「무엇이」에 해당하는 말은 어느 것인가요?',ARRAY['K1-1-u6-X04']::text[],false,'{"seq":1,"concept":"K1-1-u6-C3","difficulty":2,"kind":"mc","stem":"「꽃이 활짝 피었어요.」에서 「무엇이」에 해당하는 말은 어느 것인가요?","options":[{"t":"꽃이","correct":true},{"t":"활짝","mis":"K1-1-u6-X04"},{"t":"피었어요","mis":"K1-1-u6-X04"}],"explanation":["활짝 핀 것은 꽃이에요.","「활짝」은 어떻게, 「피었어요」는 어찌하다예요.","「~이·~가」로 끝나는 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_challenge#2','kor',1,1,'u6','L02','g1_1_kor_u6_L02_challenge','lesson_challenge','K1-1-u6-C4',2,'mc','auto','형이 공을 차는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":2,"concept":"K1-1-u6-C4","difficulty":2,"kind":"mc","stem":"형이 공을 차는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"형이 공을 차요.","correct":true},{"t":"형이 공을 던져요.","mis":"K1-1-u6-X06"},{"t":"누나가 공을 차요.","mis":"K1-1-u6-X06"}],"explanation":["그림 속 형이 발로 공을 차요.","던지는 것도, 누나도 그림과 달라요.","누가와 하는 일을 모두 맞춰요."],"asset":{"type":"scene","icon":"👦⚽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_challenge#3','kor',1,1,'u6','L02','g1_1_kor_u6_L02_challenge','lesson_challenge','K1-1-u6-C3',3,'blank','auto','빈칸에 「누가」에 해당하는 말을 넣으려고 해요. 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_challenge#4','kor',1,1,'u6','L02','g1_1_kor_u6_L02_challenge','lesson_challenge','K1-1-u6-C3',3,'mc','auto','「아기가 먹어요.」에 「무엇을」을 넣어 더 자세하게 바꾼 문장은 어느 것인가요?',ARRAY['K1-1-u6-X05','K1-1-u6-X04']::text[],false,'{"seq":4,"concept":"K1-1-u6-C3","difficulty":3,"kind":"mc","stem":"「아기가 먹어요.」에 「무엇을」을 넣어 더 자세하게 바꾼 문장은 어느 것인가요?","options":[{"t":"아기가 바나나를 먹어요.","correct":true},{"t":"아기가 먹어요 먹어요.","mis":"K1-1-u6-X05"},{"t":"바나나가 먹어요.","mis":"K1-1-u6-X04"}],"explanation":["「바나나를」을 넣어 무엇을 먹는지 알 수 있어요.","같은 말을 되풀이하거나 누가를 바꾸면 안 돼요.","「무엇을」 조각을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
