INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_challenge#6','kor',1,1,'u6','L02','g1_1_kor_u6_L02_challenge','lesson_challenge','K1-1-u6-C4',3,'mc','auto','비 오는 날 그림이에요. 그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":6,"concept":"K1-1-u6-C4","difficulty":3,"kind":"mc","stem":"비 오는 날 그림이에요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"비가 와서 우산을 써요.","correct":true},{"t":"눈이 와서 우산을 써요.","mis":"K1-1-u6-X06"},{"t":"비가 와서 모자를 벗어요.","mis":"K1-1-u6-X06"}],"explanation":["그림 속에 비와 우산이 있어요.","눈이나 모자는 그림과 달라요.","그림 속 날씨와 물건을 모두 살펴요."],"asset":{"type":"scene","icon":"🌧️☂️🧒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_challenge#7','kor',1,1,'u6','L02','g1_1_kor_u6_L02_challenge','lesson_challenge','K1-1-u6-C3',3,'ox','auto','「우유를 마셔요.」는 누가 마시는지 알 수 있는 문장이에요.',ARRAY['K1-1-u6-X05']::text[],false,'{"seq":7,"concept":"K1-1-u6-C3","difficulty":3,"kind":"ox","stem":"「우유를 마셔요.」는 누가 마시는지 알 수 있는 문장이에요.","answer":"X","reason_options":[{"t":"「누가」가 빠져서 누가 마시는지 알 수 없으니까","correct":true},{"t":"「무엇을」이 있으면 누가 했는지도 알 수 있으니까","mis":"K1-1-u6-X05"}],"mis":"K1-1-u6-X05","explanation":["「누가」가 없어 누가 마시는지 몰라요.","「동생이 우유를 마셔요」처럼 써야 해요.","세 조각이 다 있는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_challenge#8','kor',1,1,'u6','L02','g1_1_kor_u6_L02_challenge','lesson_challenge','K1-1-u6-C3',4,'mc','auto','「누가」 「무엇을」 「어찌하다」가 모두 바르게 들어간 문장은 어느 것인가요?',ARRAY['K1-1-u6-X05','K1-1-u6-X04']::text[],false,'{"seq":8,"concept":"K1-1-u6-C3","difficulty":4,"kind":"mc","stem":"「누가」 「무엇을」 「어찌하다」가 모두 바르게 들어간 문장은 어느 것인가요?","options":[{"t":"아빠가 설거지를 해요.","correct":true},{"t":"아빠가 설거지를.","mis":"K1-1-u6-X05"},{"t":"설거지가 아빠를 해요.","mis":"K1-1-u6-X04"}],"explanation":["「아빠가(누가) 설거지를(무엇을) 해요(어찌하다)」예요.","하나는 어찌하다가 빠졌고, 하나는 누가와 무엇을이 바뀌었어요.","세 조각을 하나씩 꼽아 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_challenge#9','kor',1,1,'u6','L02','g1_1_kor_u6_L02_challenge','lesson_challenge','K1-1-u6-C3',4,'essay','teacher','그림을 보고 「누가 + 무엇을 + 어찌하다」 문장을 하나 쓰고 또박또박 읽어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u6-C3","difficulty":4,"kind":"essay","stem":"그림을 보고 「누가 + 무엇을 + 어찌하다」 문장을 하나 쓰고 또박또박 읽어 보세요.","answer_guide":{"answer":"예: 강아지가 뼈다귀를 먹어요.","scoring_points":["「누가」를 바르게 썼는가","「무엇을」을 바르게 썼는가","그림에 맞는 「어찌하다」를 썼는가"]},"explanation":["누가.","무엇을.","어찌하다."],"asset":{"type":"scene","icon":"🐶🦴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L02_challenge#10','kor',1,1,'u6','L02','g1_1_kor_u6_L02_challenge','lesson_challenge','K1-1-u6-C4',4,'essay','teacher','「바람이 불어요.」를 읽고 떠오른 장면을 말하고, 나뭇잎이 어떻게 될지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u6-C4","difficulty":4,"kind":"essay","stem":"「바람이 불어요.」를 읽고 떠오른 장면을 말하고, 나뭇잎이 어떻게 될지 써 보세요.","answer_guide":{"answer":"예: 나무가 흔들리고 나뭇잎이 바람에 날려 떨어져요.","scoring_points":["문장을 읽고 장면을 떠올려 말했는가","나뭇잎의 모습을 알맞게 썼는가","문장으로 또박또박 썼는가"]},"explanation":["떠오른 장면.","나뭇잎 모습.","문장으로 쓰기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_basic#1','kor',1,1,'u6','L04','g1_1_kor_u6_L04_basic','lesson_basic','K1-1-u6-C4',1,'mc','auto','놀이터 그림을 보고 답해요. 원숭이는 어떻게 하고 있나요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":1,"concept":"K1-1-u6-C4","difficulty":1,"kind":"mc","stem":"놀이터 그림을 보고 답해요. 원숭이는 어떻게 하고 있나요?","options":[{"t":"원숭이가 달려요.","correct":true},{"t":"원숭이가 그네를 타요.","mis":"K1-1-u6-X06"},{"t":"원숭이가 자요.","mis":"K1-1-u6-X06"}],"explanation":["원숭이는 놀이터에서 달리고 있어요.","그네를 타는 것은 하마이고, 자는 동물은 없어요.","동물마다 하는 일을 하나씩 짚어요."],"asset":{"type":"scene","icon":"🛝🐒🦛🐰🐿️🐻","text":"놀이터에서 원숭이는 달리고, 하마는 그네를 타요. 토끼와 다람쥐는 시소를 타고, 곰은 모래성을 다 만들었어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_basic#2','kor',1,1,'u6','L04','g1_1_kor_u6_L04_basic','lesson_basic','K1-1-u6-C4',1,'mc','auto','놀이터 그림을 보고 답해요. 하마는 무엇을 하고 있나요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":2,"concept":"K1-1-u6-C4","difficulty":1,"kind":"mc","stem":"놀이터 그림을 보고 답해요. 하마는 무엇을 하고 있나요?","options":[{"t":"하마가 그네를 타요.","correct":true},{"t":"하마가 시소를 타요.","mis":"K1-1-u6-X06"},{"t":"하마가 모래성을 만들어요.","mis":"K1-1-u6-X06"}],"explanation":["하마는 그네를 타고 있어요.","시소는 토끼와 다람쥐, 모래성은 곰이에요.","동물마다 하는 일을 하나씩 짚어요."],"asset":{"type":"scene","icon":"🛝🐒🦛🐰🐿️🐻","text":"놀이터에서 원숭이는 달리고, 하마는 그네를 타요. 토끼와 다람쥐는 시소를 타고, 곰은 모래성을 다 만들었어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_basic#3','kor',1,1,'u6','L04','g1_1_kor_u6_L04_basic','lesson_basic','K1-1-u6-C4',1,'mc','auto','놀이터 그림을 보고 답해요. 토끼와 다람쥐는 무엇을 하나요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":3,"concept":"K1-1-u6-C4","difficulty":1,"kind":"mc","stem":"놀이터 그림을 보고 답해요. 토끼와 다람쥐는 무엇을 하나요?","options":[{"t":"토끼와 다람쥐가 시소를 타요.","correct":true},{"t":"토끼와 다람쥐가 그네를 타요.","mis":"K1-1-u6-X06"},{"t":"토끼가 혼자 시소를 타요.","mis":"K1-1-u6-X06"}],"explanation":["토끼와 다람쥐가 함께 시소를 타요.","그네는 하마가 타고, 토끼 혼자가 아니에요.","누가, 무엇을 하는지 모두 맞춰요."],"asset":{"type":"scene","icon":"🛝🐒🦛🐰🐿️🐻","text":"놀이터에서 원숭이는 달리고, 하마는 그네를 타요. 토끼와 다람쥐는 시소를 타고, 곰은 모래성을 다 만들었어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_basic#4','kor',1,1,'u6','L04','g1_1_kor_u6_L04_basic','lesson_basic','K1-1-u6-C5',1,'ox','auto','긴 문장은 뜻이 이어지는 말끼리 묶어 그 사이에서 쉬어 읽어요.',ARRAY['K1-1-u6-X07']::text[],false,'{"seq":4,"concept":"K1-1-u6-C5","difficulty":1,"kind":"ox","stem":"긴 문장은 뜻이 이어지는 말끼리 묶어 그 사이에서 쉬어 읽어요.","answer":"O","reason_options":[{"t":"뜻 덩어리마다 쉬면 듣는 사람이 잘 알아들으니까","correct":true},{"t":"긴 문장은 숨을 참고 한 번에 읽어야 하니까","mis":"K1-1-u6-X07"}],"mis":"K1-1-u6-X07","explanation":["뜻이 이어지는 말끼리 묶어 쉬어요.","한숨에 읽으면 뜻이 잘 전해지지 않아요.","묶음 사이에서 쉬어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_basic#5','kor',1,1,'u6','L04','g1_1_kor_u6_L04_basic','lesson_basic','K1-1-u6-C5',2,'mc','auto','「우리 반 친구들은 운동장에서 축구를 해요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X07','K1-1-u6-X03']::text[],true,'{"seq":5,"concept":"K1-1-u6-C5","difficulty":2,"kind":"mc","stem":"「우리 반 친구들은 운동장에서 축구를 해요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"우리 반 친구들은 ∨ 운동장에서 축구를 해요.","correct":true},{"t":"우리 ∨ 반 ∨ 친구들은 ∨ 운동장에서 ∨ 축구를 ∨ 해요.","mis":"K1-1-u6-X07"},{"t":"우리 반 친 ∨ 구들은 운동장에서 축구를 해요.","mis":"K1-1-u6-X03"}],"explanation":["「우리 반 친구들은」이 한 덩어리라 그 뒤에서 쉬어요.","낱말마다 끊거나 낱말 가운데서 끊으면 뜻이 끊겨요.","누가 덩어리 뒤에서 쉬어 봐요."],"variant_rule":{"alt":[{"stem":"「할머니께서 시장에서 사과를 사 오셨어요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"할머니께서 ∨ 시장에서 사과를 사 오셨어요.","correct":true},{"t":"할머니께서 ∨ 시장에서 ∨ 사과를 ∨ 사 ∨ 오셨어요.","mis":"K1-1-u6-X07"},{"t":"할머 ∨ 니께서 시장에서 사과를 사 오셨어요.","mis":"K1-1-u6-X03"}],"explanation":["「할머니께서」 뒤에서 쉬어요.","너무 자주 끊거나 낱말 가운데서 끊으면 뜻이 끊겨요.","누가 덩어리 뒤에서 쉬어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_basic#6','kor',1,1,'u6','L04','g1_1_kor_u6_L04_basic','lesson_basic','K1-1-u6-C4',2,'mc','auto','놀이터 그림을 보고 답해요. 곰은 모래성을 어떻게 했나요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":6,"concept":"K1-1-u6-C4","difficulty":2,"kind":"mc","stem":"놀이터 그림을 보고 답해요. 곰은 모래성을 어떻게 했나요?","options":[{"t":"곰이 모래성을 다 만들었어요.","correct":true},{"t":"곰이 모래성을 부수었어요.","mis":"K1-1-u6-X06"},{"t":"곰이 그네를 만들었어요.","mis":"K1-1-u6-X06"}],"explanation":["곰은 모래성을 다 만들었어요.","모래성을 부수거나 그네를 만들지 않았어요.","그림 속 물건과 하는 일을 맞춰요."],"asset":{"type":"scene","icon":"🛝🐒🦛🐰🐿️🐻","text":"놀이터에서 원숭이는 달리고, 하마는 그네를 타요. 토끼와 다람쥐는 시소를 타고, 곰은 모래성을 다 만들었어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_basic#7','kor',1,1,'u6','L04','g1_1_kor_u6_L04_basic','lesson_basic','K1-1-u6-C4',2,'mc','auto','운동장에서 축구하는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],true,'{"seq":7,"concept":"K1-1-u6-C4","difficulty":2,"kind":"mc","stem":"운동장에서 축구하는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"친구들이 운동장에서 축구를 해요.","correct":true},{"t":"친구들이 교실에서 축구를 해요.","mis":"K1-1-u6-X06"},{"t":"친구들이 운동장에서 줄넘기를 해요.","mis":"K1-1-u6-X06"}],"explanation":["친구들이 운동장에서 축구를 하고 있어요.","곳(교실)이나 하는 일(줄넘기)이 그림과 달라요.","누가·어디서·무엇을 셋을 맞춰요."],"asset":{"type":"scene","icon":"🏫⚽🧒"},"variant_rule":{"alt":[{"stem":"교실에서 책을 읽는 그림이에요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"친구들이 교실에서 책을 읽어요.","correct":true},{"t":"친구들이 운동장에서 책을 읽어요.","mis":"K1-1-u6-X06"},{"t":"친구들이 교실에서 노래를 불러요.","mis":"K1-1-u6-X06"}],"explanation":["친구들이 교실에서 책을 읽고 있어요.","곳이나 하는 일이 그림과 달라요.","누가·어디서·무엇을 셋을 맞춰요."],"asset":{"type":"scene","icon":"🏫📖🧒"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_basic#8','kor',1,1,'u6','L04','g1_1_kor_u6_L04_basic','lesson_basic','K1-1-u6-C4',2,'match','auto','놀이터 그림을 보고 동물과 하는 일을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u6-C4","difficulty":2,"kind":"match","stem":"놀이터 그림을 보고 동물과 하는 일을 이으세요.","pairs":[{"l":"원숭이","r":"달려요"},{"l":"하마","r":"그네를 타요"},{"l":"곰","r":"모래성을 만들었어요"}],"mis":"K1-1-u6-X06","explanation":["원숭이는 달리고, 하마는 그네를 타고, 곰은 모래성을 만들었어요.","동물마다 하는 일이 달라요.","그림에서 하나씩 짚어 봐요."],"asset":{"type":"scene","icon":"🛝🐒🦛🐰🐿️🐻","text":"놀이터에서 원숭이는 달리고, 하마는 그네를 타요. 토끼와 다람쥐는 시소를 타고, 곰은 모래성을 다 만들었어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_basic#9','kor',1,1,'u6','L04','g1_1_kor_u6_L04_basic','lesson_basic','K1-1-u6-C5',2,'mc','auto','긴 문장에서 쉬어 읽을 곳을 정하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X07']::text[],false,'{"seq":9,"concept":"K1-1-u6-C5","difficulty":2,"kind":"mc","stem":"긴 문장에서 쉬어 읽을 곳을 정하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻이 이어지는 말끼리 묶고 그 사이에서 쉬어요","correct":true},{"t":"글자 다섯 개마다 쉬어요","mis":"K1-1-u6-X07"},{"t":"숨이 찰 때 아무 데서나 쉬어요","mis":"K1-1-u6-X07"}],"explanation":["뜻 덩어리 사이에서 쉬어야 뜻이 잘 전해져요.","글자 수나 숨에 맞춰 쉬면 뜻이 끊겨요.","말끼리 괄호로 묶어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
