INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_challenge#1','kor',1,1,'u6','L04','g1_1_kor_u6_L04_challenge','lesson_challenge','K1-1-u6-C4',2,'mc','auto','놀이터 그림에 알맞지 않은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":1,"concept":"K1-1-u6-C4","difficulty":2,"kind":"mc","stem":"놀이터 그림에 알맞지 않은 문장은 어느 것인가요?","options":[{"t":"곰이 그네를 타요.","correct":true},{"t":"원숭이가 달려요.","mis":"K1-1-u6-X06"},{"t":"하마가 그네를 타요.","mis":"K1-1-u6-X06"}],"explanation":["곰은 그네가 아니라 모래성을 만들었어요.","다른 두 문장은 그림과 맞아요.","문장마다 그림과 하나씩 맞춰요."],"asset":{"type":"scene","icon":"🛝🐒🦛🐰🐿️🐻","text":"놀이터에서 원숭이는 달리고, 하마는 그네를 타요. 토끼와 다람쥐는 시소를 타고, 곰은 모래성을 다 만들었어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_challenge#2','kor',1,1,'u6','L04','g1_1_kor_u6_L04_challenge','lesson_challenge','K1-1-u6-C5',2,'mc','auto','「선생님께서 칠판에 글씨를 쓰세요.」를 가장 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X03']::text[],false,'{"seq":2,"concept":"K1-1-u6-C5","difficulty":2,"kind":"mc","stem":"「선생님께서 칠판에 글씨를 쓰세요.」를 가장 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"선생님께서 ∨ 칠판에 글씨를 쓰세요.","correct":true},{"t":"선생님께서 칠판에 글 ∨ 씨를 쓰세요.","mis":"K1-1-u6-X03"},{"t":"선생님 ∨ 께서 ∨ 칠판 ∨ 에 글씨를 쓰세요.","mis":"K1-1-u6-X03"}],"explanation":["「선생님께서」 뒤에서 쉬어요.","「글 ∨ 씨」·「선생님 ∨ 께서」는 낱말 가운데서 끊었어요.","낱말은 붙이고 덩어리 사이에서 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_challenge#3','kor',1,1,'u6','L04','g1_1_kor_u6_L04_challenge','lesson_challenge','K1-1-u6-C4',3,'mc','auto','놀이터 그림에 알맞은 문장만 모은 것은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":3,"concept":"K1-1-u6-C4","difficulty":3,"kind":"mc","stem":"놀이터 그림에 알맞은 문장만 모은 것은 어느 것인가요?","options":[{"t":"원숭이가 달려요. · 곰이 모래성을 만들었어요.","correct":true},{"t":"원숭이가 달려요. · 하마가 시소를 타요.","mis":"K1-1-u6-X06"},{"t":"토끼가 그네를 타요. · 곰이 모래성을 만들었어요.","mis":"K1-1-u6-X06"}],"explanation":["원숭이는 달리고 곰은 모래성을 만들었어요.","하마는 그네를, 토끼는 시소를 타요.","두 문장 모두 그림과 맞는지 살펴요."],"asset":{"type":"scene","icon":"🛝🐒🦛🐰🐿️🐻","text":"놀이터에서 원숭이는 달리고, 하마는 그네를 타요. 토끼와 다람쥐는 시소를 타고, 곰은 모래성을 다 만들었어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_challenge#4','kor',1,1,'u6','L04','g1_1_kor_u6_L04_challenge','lesson_challenge','K1-1-u6-C5',3,'mc','auto','「어제 나는 할머니 댁에서 감을 먹었어요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X07','K1-1-u6-X03']::text[],false,'{"seq":4,"concept":"K1-1-u6-C5","difficulty":3,"kind":"mc","stem":"「어제 나는 할머니 댁에서 감을 먹었어요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"어제 나는 ∨ 할머니 댁에서 ∨ 감을 먹었어요.","correct":true},{"t":"어제 나는 할머니 ∨ 댁에서 감을 ∨ 먹었어요.","mis":"K1-1-u6-X07"},{"t":"어제 나 ∨ 는 할머니 댁에서 감을 먹었어요.","mis":"K1-1-u6-X03"}],"explanation":["「어제 나는」, 「할머니 댁에서」, 「감을 먹었어요」로 묶어요.","「할머니 ∨ 댁에서」는 뜻 덩어리를 가르고, 「나 ∨ 는」은 낱말 가운데서 끊었어요.","뜻이 이어지는 말끼리 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
