INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_challenge#6','kor',1,1,'u6','L04','g1_1_kor_u6_L04_challenge','lesson_challenge','K1-1-u6-C5',3,'ox','auto','긴 문장을 낱말마다 모두 쉬어 읽으면 가장 또박또박 잘 읽은 거예요.',ARRAY['K1-1-u6-X07']::text[],false,'{"seq":6,"concept":"K1-1-u6-C5","difficulty":3,"kind":"ox","stem":"긴 문장을 낱말마다 모두 쉬어 읽으면 가장 또박또박 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"너무 자주 쉬면 뜻이 끊겨 듣기 어려우니까","correct":true},{"t":"쉬는 곳이 많을수록 좋으니까","mis":"K1-1-u6-X07"}],"mis":"K1-1-u6-X07","explanation":["낱말마다 끊으면 뜻이 끊겨요.","뜻 덩어리 사이에서만 쉬어요.","또박또박은 정확하게, 쉬기는 알맞게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_challenge#7','kor',1,1,'u6','L04','g1_1_kor_u6_L04_challenge','lesson_challenge','K1-1-u6-C4',3,'mc','auto','「아기가 울어요.」를 읽고 떠올린 장면으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X01','K1-1-u6-X06']::text[],false,'{"seq":7,"concept":"K1-1-u6-C4","difficulty":3,"kind":"mc","stem":"「아기가 울어요.」를 읽고 떠올린 장면으로 알맞은 것은 어느 것인가요?","options":[{"t":"아기가 눈물을 흘리는 장면","correct":true},{"t":"아기가 활짝 웃는 장면","mis":"K1-1-u6-X01"},{"t":"아기가 쿨쿨 자는 장면","mis":"K1-1-u6-X06"}],"explanation":["「울어요」를 읽으면 눈물 흘리는 아기가 떠올라요.","「웃어요」로 잘못 읽거나 다른 장면을 떠올리면 안 돼요.","읽고 나서 머릿속 그림을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_challenge#8','kor',1,1,'u6','L04','g1_1_kor_u6_L04_challenge','lesson_challenge','K1-1-u6-C5',4,'mc','auto','「키가 큰 형이 공을 높이 던졌어요.」를 뜻이 잘 통하게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X07','K1-1-u6-X03']::text[],false,'{"seq":8,"concept":"K1-1-u6-C5","difficulty":4,"kind":"mc","stem":"「키가 큰 형이 공을 높이 던졌어요.」를 뜻이 잘 통하게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"키가 큰 형이 ∨ 공을 높이 던졌어요.","correct":true},{"t":"키가 ∨ 큰 형이 공을 ∨ 높이 던졌어요.","mis":"K1-1-u6-X07"},{"t":"키가 큰 형 ∨ 이 공을 높이 던졌어요.","mis":"K1-1-u6-X03"}],"explanation":["「키가 큰 형이」가 한 덩어리라 그 뒤에서 쉬어요.","덩어리를 가르거나 낱말 가운데서 끊으면 뜻이 흐려져요.","누가 덩어리를 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_challenge#9','kor',1,1,'u6','L04','g1_1_kor_u6_L04_challenge','lesson_challenge','K1-1-u6-C4',4,'essay','teacher','놀이터 그림에서 동물 하나를 골라 「누가 + 무엇을 + 어찌하다」 문장으로 쓰고, 그 문장이 그림과 맞는 까닭을 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u6-C4","difficulty":4,"kind":"essay","stem":"놀이터 그림에서 동물 하나를 골라 「누가 + 무엇을 + 어찌하다」 문장으로 쓰고, 그 문장이 그림과 맞는 까닭을 말해 보세요.","answer_guide":{"answer":"예: 하마가 그네를 타요. — 그림에서 하마가 그네에 앉아 있으니까요.","scoring_points":["그림에 나온 동물로 문장을 썼는가","하는 일이 그림과 맞는가","맞는 까닭을 그림에서 찾아 말했는가"]},"explanation":["동물 고르기.","그림에 맞는 문장.","까닭 말하기."],"asset":{"type":"scene","icon":"🛝🐒🦛🐰🐿️🐻","text":"놀이터에서 원숭이는 달리고, 하마는 그네를 타요. 토끼와 다람쥐는 시소를 타고, 곰은 모래성을 다 만들었어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L04_challenge#10','kor',1,1,'u6','L04','g1_1_kor_u6_L04_challenge','lesson_challenge','K1-1-u6-C5',4,'essay','teacher','「우리 반 친구들은 운동장에서 축구를 해요.」에 쉬어 읽을 곳 한 곳에 ∨ 표시를 하고, 그곳에서 쉰 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u6-C5","difficulty":4,"kind":"essay","stem":"「우리 반 친구들은 운동장에서 축구를 해요.」에 쉬어 읽을 곳 한 곳에 ∨ 표시를 하고, 그곳에서 쉰 까닭을 써 보세요.","answer_guide":{"answer":"예: 우리 반 친구들은 ∨ 운동장에서 축구를 해요. — 「우리 반 친구들은」이 누가를 나타내는 한 덩어리라서요.","scoring_points":["뜻 덩어리 사이에 ∨ 를 했는가","낱말 가운데서 끊지 않았는가","쉰 까닭을 뜻 덩어리로 말했는가"]},"explanation":["∨ 표시.","낱말 안 끊지 않기.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_basic#1','kor',1,1,'u6','L06','g1_1_kor_u6_L06_basic','lesson_basic','K1-1-u6-C6',1,'mc','auto','「?」의 이름은 무엇인가요?',ARRAY['K1-1-u6-X08']::text[],true,'{"seq":1,"concept":"K1-1-u6-C6","difficulty":1,"kind":"mc","stem":"「?」의 이름은 무엇인가요?","options":[{"t":"물음표","correct":true},{"t":"마침표","mis":"K1-1-u6-X08"},{"t":"쉼표","mis":"K1-1-u6-X08"}],"explanation":["이 부호는 물음표예요.","물음표는 묻는 문장 끝에 써요.","모양과 쓰임을 함께 떠올리며 이름을 익혀요."],"variant_rule":{"punct":{"ask":"name","mis":{"name":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_basic#2','kor',1,1,'u6','L06','g1_1_kor_u6_L06_basic','lesson_basic','K1-1-u6-C6',1,'mc','auto','「!」의 이름은 무엇인가요?',ARRAY['K1-1-u6-X08']::text[],true,'{"seq":2,"concept":"K1-1-u6-C6","difficulty":1,"kind":"mc","stem":"「!」의 이름은 무엇인가요?","options":[{"t":"느낌표","correct":true},{"t":"물음표","mis":"K1-1-u6-X08"},{"t":"마침표","mis":"K1-1-u6-X08"}],"explanation":["이 부호는 느낌표예요.","느낌표는 느낌을 나타내는 문장 끝에 써요.","모양과 쓰임을 함께 떠올리며 이름을 익혀요."],"variant_rule":{"punct":{"ask":"name","mis":{"name":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
