INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_basic#8','kor',1,1,'u6','L06','g1_1_kor_u6_L06_basic','lesson_basic','K1-1-u6-C6',2,'mc','auto','문장 부호가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X08']::text[],false,'{"seq":8,"concept":"K1-1-u6-C6","difficulty":2,"kind":"mc","stem":"문장 부호가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"문장의 뜻을 돕고, 문장을 나누어 읽기 쉽게 해요","correct":true},{"t":"글자를 예쁘게 꾸며 줘요","mis":"K1-1-u6-X08"},{"t":"문장을 더 길게 만들어 줘요","mis":"K1-1-u6-X08"}],"explanation":["문장 부호는 뜻을 돕고 읽기 쉽게 해 줘요.","꾸미거나 길게 하려고 쓰는 것이 아니에요.","부호가 있을 때와 없을 때를 견줘 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_basic#9','kor',1,1,'u6','L06','g1_1_kor_u6_L06_basic','lesson_basic','K1-1-u6-C7',2,'ox','auto','쉼표와 마침표는 칸의 왼쪽 아래에 작게 써요.',ARRAY['K1-1-u6-X16']::text[],true,'{"seq":9,"concept":"K1-1-u6-C7","difficulty":2,"kind":"ox","stem":"쉼표와 마침표는 칸의 왼쪽 아래에 작게 써요.","answer":"O","reason_options":[{"t":"칸 왼쪽 아래에 작게 써야 글자와 헷갈리지 않으니까","correct":true},{"t":"칸 한가운데에 크게 써야 잘 보이니까","mis":"K1-1-u6-X16"}],"mis":"K1-1-u6-X16","explanation":["쉼표와 마침표는 칸 왼쪽 아래에 써요.","한가운데에 크게 쓰면 글자처럼 보여요.","칸을 넷으로 나눠 왼쪽 아래를 찾아요."],"variant_rule":{"alt":[{"stem":"쉼표는 칸 한가운데에 크게 써야 해요.","answer":"X","reason_options":[{"t":"쉼표는 칸 왼쪽 아래에 작게 쓰니까","correct":true},{"t":"크게 써야 잘 보이니까","mis":"K1-1-u6-X16"}],"explanation":["쉼표는 칸 왼쪽 아래에 작게 써요.","크게 쓰면 글자와 헷갈려요.","칸을 넷으로 나눠 왼쪽 아래를 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
