INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_challenge#2','kor',1,1,'u6','L06','g1_1_kor_u6_L06_challenge','lesson_challenge','K1-1-u6-C6',2,'mc','auto','「언제 우리 집에 올래?」는 어떤 문장인가요?',ARRAY['K1-1-u6-X09']::text[],true,'{"seq":2,"concept":"K1-1-u6-C6","difficulty":2,"kind":"mc","stem":"「언제 우리 집에 올래?」는 어떤 문장인가요?","options":[{"t":"묻는 문장","correct":true},{"t":"느낌을 나타내는 문장","mis":"K1-1-u6-X09"},{"t":"설명하는 문장","mis":"K1-1-u6-X09"}],"explanation":["끝에 물음표( ? )가 있는 묻는 문장이에요.","물음표는 묻는 문장, 느낌표는 느낌을 나타내는 문장, 마침표는 설명하는 문장 끝에 써요.","문장 끝 부호와 문장의 뜻을 함께 살펴요."],"variant_rule":{"punct":{"ask":"type","mis":{"type":"X09"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_challenge#3','kor',1,1,'u6','L06','g1_1_kor_u6_L06_challenge','lesson_challenge','K1-1-u6-C7',3,'mc','auto','끝에 물음표( ? )를 써야 하는 문장은 어느 것인가요?',ARRAY['K1-1-u6-X09']::text[],false,'{"seq":3,"concept":"K1-1-u6-C7","difficulty":3,"kind":"mc","stem":"끝에 물음표( ? )를 써야 하는 문장은 어느 것인가요?","options":[{"t":"이 책은 누구 거야","correct":true},{"t":"오늘 날씨가 참 맑아요","mis":"K1-1-u6-X09"},{"t":"와, 정말 신난다","mis":"K1-1-u6-X09"}],"explanation":["「누구 거야」는 묻는 문장이라 물음표를 써요.","설명하는 문장은 마침표, 느낌을 나타내는 문장은 느낌표예요.","묻는 말(누구·어디·뭐)이 있는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
