INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_challenge#7','kor',1,1,'u6','L06','g1_1_kor_u6_L06_challenge','lesson_challenge','K1-1-u6-C6',3,'mc','auto','물음표와 느낌표의 쓰임을 바르게 말한 친구는 누구인가요?',ARRAY['K1-1-u6-X08']::text[],false,'{"seq":7,"concept":"K1-1-u6-C6","difficulty":3,"kind":"mc","stem":"물음표와 느낌표의 쓰임을 바르게 말한 친구는 누구인가요?","options":[{"t":"지안: 물음표는 물을 때, 느낌표는 놀라거나 기쁠 때 써요.","correct":true},{"t":"태민: 물음표는 기쁠 때, 느낌표는 물을 때 써요.","mis":"K1-1-u6-X08"},{"t":"하린: 둘 다 부르는 말 뒤에 써요.","mis":"K1-1-u6-X08"}],"explanation":["물음표는 묻는 문장, 느낌표는 느낌을 나타내는 문장에 써요.","둘을 바꾸거나 부르는 말 뒤에 쓰면 안 돼요.","모양과 쓰임을 함께 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_challenge#8','kor',1,1,'u6','L06','g1_1_kor_u6_L06_challenge','lesson_challenge','K1-1-u6-C7',4,'mc','auto','다음 문장의 ◯에 알맞은 문장 부호는 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_challenge#9','kor',1,1,'u6','L06','g1_1_kor_u6_L06_challenge','lesson_challenge','K1-1-u6-C7',4,'essay','teacher','묻는 문장, 느낌을 나타내는 문장, 설명하는 문장을 하나씩 쓰고 끝에 알맞은 부호를 붙여 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u6-C7","difficulty":4,"kind":"essay","stem":"묻는 문장, 느낌을 나타내는 문장, 설명하는 문장을 하나씩 쓰고 끝에 알맞은 부호를 붙여 보세요.","answer_guide":{"answer":"예: 너는 무엇을 좋아하니? / 와, 정말 예쁘다! / 나는 사과를 좋아해요.","scoring_points":["세 종류의 문장을 하나씩 썼는가","끝에 알맞은 부호(? ! .)를 붙였는가","부호를 칸 알맞은 자리에 썼는가"]},"explanation":["세 종류 문장.","알맞은 끝 부호.","바른 자리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L06_challenge#10','kor',1,1,'u6','L06','g1_1_kor_u6_L06_challenge','lesson_challenge','K1-1-u6-C6',4,'essay','teacher','「할머니, 나무를 심어요.」와 「할머니 나무를 심어요.」는 뜻이 어떻게 다른지 쉼표를 생각하며 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u6-C6","difficulty":4,"kind":"essay","stem":"「할머니, 나무를 심어요.」와 「할머니 나무를 심어요.」는 뜻이 어떻게 다른지 쉼표를 생각하며 말해 보세요.","answer_guide":{"answer":"쉼표가 있으면 할머니를 부르며 나무를 심는다고 말하는 것이고, 쉼표가 없으면 할머니의 나무를 심는다는 뜻이 될 수 있어요.","scoring_points":["쉼표가 있는 문장의 뜻을 말했는가","쉼표가 없는 문장의 뜻을 말했는가","쉼표가 뜻을 바꾼다는 것을 말했는가"]},"explanation":["쉼표 있을 때.","쉼표 없을 때.","쉼표가 하는 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#1','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C10',1,'mc','auto','「해바라기 씨에서 나온 기린」에서 기린은 어디에서 나왔나요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":1,"concept":"K1-1-u6-C10","difficulty":1,"kind":"mc","stem":"「해바라기 씨에서 나온 기린」에서 기린은 어디에서 나왔나요?","options":[{"t":"해바라기 씨","correct":true},{"t":"연필꽂이","mis":"K1-1-u6-X14"},{"t":"꽃병","mis":"K1-1-u6-X14"}],"explanation":["해바라기 씨가 구르더니 기린이 되었어요.","연필꽂이나 꽃병은 이야기에 나오지 않아요.","셋째 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#2','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C8',1,'mc','auto','쉼표( , ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?',ARRAY['K1-1-u6-X11']::text[],true,'{"seq":2,"concept":"K1-1-u6-C8","difficulty":1,"kind":"mc","stem":"쉼표( , ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?","options":[{"t":"∨ (조금 쉬어)","correct":true},{"t":"≫ (조금 더 쉬어)","mis":"K1-1-u6-X11"},{"t":"아무 표시도 하지 않아요","mis":"K1-1-u6-X11"}],"explanation":["쉼표 뒤에는 ∨ 를 하고 조금 쉬어요.","≫ 는 마침표·물음표·느낌표 뒤에 해요.","쉼표에서 손가락 하나만큼 쉬어요."],"variant_rule":{"alt":[{"stem":"느낌표( ! ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?","options":[{"t":"≫ (조금 더 쉬어)","correct":true},{"t":"∨ (조금 쉬어)","mis":"K1-1-u6-X11"},{"t":"아무 표시도 하지 않아요","mis":"K1-1-u6-X11"}],"explanation":["느낌표 뒤에는 ≫ 를 하고 조금 더 쉬어요.","∨ 는 쉼표 뒤에 해요.","끝 부호에서 손가락 둘만큼 쉬어요."]},{"stem":"물음표( ? ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?","options":[{"t":"≫ (조금 더 쉬어)","correct":true},{"t":"∨ (조금 쉬어)","mis":"K1-1-u6-X11"},{"t":"아무 표시도 하지 않아요","mis":"K1-1-u6-X11"}],"explanation":["물음표 뒤에는 ≫ 를 하고 조금 더 쉬어요.","∨ 는 쉼표 뒤에 해요.","끝 부호에서 손가락 둘만큼 쉬어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#3','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C9',1,'mc','auto','「너는 어디에 가니?」를 어떻게 읽으면 좋을까요?',ARRAY['K1-1-u6-X12','K1-1-u6-X13']::text[],true,'{"seq":3,"concept":"K1-1-u6-C9","difficulty":1,"kind":"mc","stem":"「너는 어디에 가니?」를 어떻게 읽으면 좋을까요?","options":[{"t":"끝을 살짝 올려 묻듯이 읽어요","correct":true},{"t":"느낌을 살려 힘 있게 읽어요","mis":"K1-1-u6-X12"},{"t":"끝을 내려 차분하게 읽어요","mis":"K1-1-u6-X13"}],"explanation":["묻는 문장은 끝을 살짝 올려 읽어요.","끝을 내리거나 힘주어 외치면 묻는 느낌이 나지 않아요.","물음표( ? )를 보면 끝을 올려 읽어요."],"variant_rule":{"punct":{"ask":"read","mis":{"read":"X12","up":"X13"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#4','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C10',1,'mc','auto','씨가 데굴데굴 구르더니 무엇이 되었나요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":4,"concept":"K1-1-u6-C10","difficulty":1,"kind":"mc","stem":"씨가 데굴데굴 구르더니 무엇이 되었나요?","options":[{"t":"아주 작은 기린","correct":true},{"t":"커다란 해바라기","mis":"K1-1-u6-X14"},{"t":"작은 다람쥐","mis":"K1-1-u6-X14"}],"explanation":["씨가 구르더니 아주 작은 기린이 되었어요.","해바라기는 처음부터 피어 있었고, 다람쥐는 나오지 않아요.","셋째 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#5','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C8',2,'mc','auto','「하람아, 같이 놀자. 공원에 누구랑 갔어?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],true,'{"seq":5,"concept":"K1-1-u6-C8","difficulty":2,"kind":"mc","stem":"「하람아, 같이 놀자. 공원에 누구랑 갔어?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?","options":[{"t":"하람아,∨ 같이 놀자.≫ 공원에 누구랑 갔어?","correct":true},{"t":"하람아,≫ 같이 놀자.∨ 공원에 누구랑 갔어?","mis":"K1-1-u6-X11"},{"t":"하람아,∨ 같이 놀자.≫ 공∨원에 누구랑 갔어?","mis":"K1-1-u6-X03"}],"explanation":["쉼표( , ) 뒤에는 ∨(조금 쉬어), 마침표·물음표·느낌표 뒤에는 ≫(조금 더 쉬어)를 해요.","쉬는 길이를 바꾸거나 낱말 가운데서 쉬면 뜻이 잘 전해지지 않아요.","부호를 찾아 그 뒤에 알맞은 표시를 해요."],"variant_rule":{"punct":{"ask":"pause","mis":{"swap":"X11","same":"X11","split":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#6','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C8',2,'mc','auto','이야기 속 「"우아, 살아 있는 진짜 기린이다!"」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],false,'{"seq":6,"concept":"K1-1-u6-C8","difficulty":2,"kind":"mc","stem":"이야기 속 「\"우아, 살아 있는 진짜 기린이다!\"」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?","options":[{"t":"우아,∨ 살아 있는 진짜 기린이다!","correct":true},{"t":"우아,≫ 살아 있는 진짜 기린이다!","mis":"K1-1-u6-X11"},{"t":"우∨아, 살아 있는 진짜 기린이다!","mis":"K1-1-u6-X03"}],"explanation":["「우아,」의 쉼표 뒤에 ∨ 를 해요.","쉼표 뒤에 ≫ 를 하거나 「우∨아」처럼 낱말 가운데서 끊으면 안 돼요.","부호 뒤에만 표시해요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#7','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C9',2,'mc','auto','「야호, 우리 반이 이겼다!」를 어떻게 읽으면 좋을까요?',ARRAY['K1-1-u6-X12']::text[],true,'{"seq":7,"concept":"K1-1-u6-C9","difficulty":2,"kind":"mc","stem":"「야호, 우리 반이 이겼다!」를 어떻게 읽으면 좋을까요?","options":[{"t":"느낌을 살려 힘 있게 읽어요","correct":true},{"t":"끝을 살짝 올려 묻듯이 읽어요","mis":"K1-1-u6-X12"},{"t":"끝을 내려 차분하게 읽어요","mis":"K1-1-u6-X12"}],"explanation":["느낌을 나타내는 문장은 느낌을 살려 힘 있게 읽어요.","밋밋하게 읽으면 놀람이나 기쁨이 전해지지 않아요.","느낌표( ! )를 보면 느낌을 살려 읽어요."],"variant_rule":{"punct":{"ask":"read","mis":{"read":"X12","up":"X13"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#8','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C9',2,'ox','auto','문장 부호와 상관없이 모든 문장을 똑같은 목소리로 읽어야 실감 나요.',ARRAY['K1-1-u6-X12']::text[],false,'{"seq":8,"concept":"K1-1-u6-C9","difficulty":2,"kind":"ox","stem":"문장 부호와 상관없이 모든 문장을 똑같은 목소리로 읽어야 실감 나요.","answer":"X","reason_options":[{"t":"부호에 맞게 끝을 올리거나 느낌을 살려야 실감 나니까","correct":true},{"t":"목소리를 바꾸면 틀리게 읽는 거니까","mis":"K1-1-u6-X12"}],"mis":"K1-1-u6-X12","explanation":["부호를 살려 목소리를 바꿔 읽어야 실감 나요.","모든 문장을 똑같이 읽으면 밋밋해요.","물음표·느낌표를 보면 목소리를 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#9','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C9',2,'match','auto','문장 부호와 읽는 법을 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u6-C9","difficulty":2,"kind":"match","stem":"문장 부호와 읽는 법을 이으세요.","pairs":[{"l":"?","r":"끝을 살짝 올려 읽어요"},{"l":"!","r":"느낌을 살려 힘 있게 읽어요"},{"l":".","r":"끝을 내려 차분하게 읽어요"}],"mis":"K1-1-u6-X12","explanation":["물음표는 끝을 올려, 느낌표는 느낌을 살려, 마침표는 차분하게 읽어요.","부호마다 읽는 목소리가 달라요.","손을 위·아래로 움직이며 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_basic#10','kor',1,1,'u6','L08','g1_1_kor_u6_L08_basic','lesson_basic','K1-1-u6-C8',3,'error','auto','로아가 쉬어 읽기 표시를 했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#1','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C10',2,'mc','auto','기린이 「여기는 어디야?」라고 물었을 때 내가 한 대답은 어느 것인가요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":1,"concept":"K1-1-u6-C10","difficulty":2,"kind":"mc","stem":"기린이 「여기는 어디야?」라고 물었을 때 내가 한 대답은 어느 것인가요?","options":[{"t":"우리 집 마당이야.","correct":true},{"t":"해바라기 밭이야.","mis":"K1-1-u6-X14"},{"t":"동물원이야.","mis":"K1-1-u6-X14"}],"explanation":["「우리 집 마당이야.」라고 대답했어요.","해바라기 밭이나 동물원이라고 하지 않았어요.","여섯째 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#2','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C8',2,'mc','auto','「와, 바다가 정말 넓구나! 할머니 댁은 시골에 있어요.」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],true,'{"seq":2,"concept":"K1-1-u6-C8","difficulty":2,"kind":"mc","stem":"「와, 바다가 정말 넓구나! 할머니 댁은 시골에 있어요.」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?","options":[{"t":"와,∨ 바다가 정말 넓구나!≫ 할머니 댁은 시골에 있어요.","correct":true},{"t":"와,∨ 바다가 정말 넓구나!∨ 할머니 댁은 시골에 있어요.","mis":"K1-1-u6-X11"},{"t":"와,∨ 바다가 정말 넓구나!≫ 할∨머니 댁은 시골에 있어요.","mis":"K1-1-u6-X03"}],"explanation":["쉼표( , ) 뒤에는 ∨(조금 쉬어), 마침표·물음표·느낌표 뒤에는 ≫(조금 더 쉬어)를 해요.","쉬는 길이를 바꾸거나 낱말 가운데서 쉬면 뜻이 잘 전해지지 않아요.","부호를 찾아 그 뒤에 알맞은 표시를 해요."],"variant_rule":{"punct":{"ask":"pause","mis":{"swap":"X11","same":"X11","split":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#3','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C10',3,'mc','auto','기린이 내 주머니에 쏙 들어간 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":3,"concept":"K1-1-u6-C10","difficulty":3,"kind":"mc","stem":"기린이 내 주머니에 쏙 들어간 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 방을 구경하러 가려고","correct":true},{"t":"무서운 동물을 피해 숨으려고","mis":"K1-1-u6-X14"},{"t":"해바라기 씨를 먹으려고","mis":"K1-1-u6-X14"}],"explanation":["「내 방 구경할래?」에 고개를 끄덕이고 주머니에 들어갔어요.","숨거나 씨를 먹으려는 이야기는 없어요.","앞 줄과 이어서 까닭을 찾아요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#4','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C9',3,'mc','auto','「"우아, 살아 있는 진짜 기린이다!"」를 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K1-1-u6-X12','K1-1-u6-X13']::text[],false,'{"seq":4,"concept":"K1-1-u6-C9","difficulty":3,"kind":"mc","stem":"「\"우아, 살아 있는 진짜 기린이다!\"」를 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"깜짝 놀라고 신기한 목소리","correct":true},{"t":"졸리고 심심한 목소리","mis":"K1-1-u6-X12"},{"t":"끝을 올려 묻는 목소리","mis":"K1-1-u6-X13"}],"explanation":["느낌표가 있고 「우아」가 있어 놀라고 신기한 느낌을 살려요.","밋밋하게 읽거나 묻듯이 읽으면 느낌이 달라져요.","부호와 인물의 마음을 함께 살펴요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#5','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C9',3,'mc','auto','「고양이가 소파에서 자요.」를 어떻게 읽으면 좋을까요?',ARRAY['K1-1-u6-X13','K1-1-u6-X12']::text[],true,'{"seq":5,"concept":"K1-1-u6-C9","difficulty":3,"kind":"mc","stem":"「고양이가 소파에서 자요.」를 어떻게 읽으면 좋을까요?","options":[{"t":"끝을 내려 차분하게 읽어요","correct":true},{"t":"끝을 살짝 올려 묻듯이 읽어요","mis":"K1-1-u6-X13"},{"t":"느낌을 살려 힘 있게 읽어요","mis":"K1-1-u6-X12"}],"explanation":["설명하는 문장은 끝을 내려 차분하게 읽어요.","끝을 올리면 묻는 말처럼 들려요.","마침표( . )를 보면 차분하게 끝맺어요."],"variant_rule":{"punct":{"ask":"read","mis":{"read":"X12","up":"X13"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#6','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C8',3,'mc','auto','쉬어 읽기 표시를 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X07']::text[],false,'{"seq":6,"concept":"K1-1-u6-C8","difficulty":3,"kind":"mc","stem":"쉬어 읽기 표시를 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"알맞게 쉬어 읽어 뜻이 잘 전해지게 하려고","correct":true},{"t":"글씨를 예쁘게 꾸미려고","mis":"K1-1-u6-X11"},{"t":"쉬지 않고 빨리 읽으려고","mis":"K1-1-u6-X07"}],"explanation":["표시를 보고 알맞게 쉬면 듣는 사람이 뜻을 잘 알아요.","꾸미거나 빨리 읽으려는 것이 아니에요.","표시대로 쉬어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#7','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C9',3,'error','auto','하린이가 「여기는 어디야?」를 끝을 내려 「여기는 어디야.」처럼 읽었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#8','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C8',4,'mc','auto','「선생님, 책을 다 읽었어요. 이 꽃 이름이 뭐예요?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?',ARRAY['K1-1-u6-X11']::text[],true,'{"seq":8,"concept":"K1-1-u6-C8","difficulty":4,"kind":"mc","stem":"「선생님, 책을 다 읽었어요. 이 꽃 이름이 뭐예요?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?","options":[{"t":"선생님,∨ 책을 다 읽었어요.≫ 이 꽃 이름이 뭐예요?","correct":true},{"t":"선생님,≫ 책을 다 읽었어요.∨ 이 꽃 이름이 뭐예요?","mis":"K1-1-u6-X11"},{"t":"선생님,∨ 책을 다 읽었어요.∨ 이 꽃 이름이 뭐예요?","mis":"K1-1-u6-X11"}],"explanation":["쉼표( , ) 뒤에는 ∨(조금 쉬어), 마침표·물음표·느낌표 뒤에는 ≫(조금 더 쉬어)를 해요.","쉬는 길이를 바꾸거나 낱말 가운데서 쉬면 뜻이 잘 전해지지 않아요.","부호를 찾아 그 뒤에 알맞은 표시를 해요."],"variant_rule":{"punct":{"ask":"pause","mis":{"swap":"X11","same":"X11","split":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#9','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C8',4,'essay','teacher','「우리 집 마당이야. 내 방 구경할래?」에 쉬어 읽기 표시를 하고, 두 문장을 각각 어떻게 읽을지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u6-C8","difficulty":4,"kind":"essay","stem":"「우리 집 마당이야. 내 방 구경할래?」에 쉬어 읽기 표시를 하고, 두 문장을 각각 어떻게 읽을지 말해 보세요.","answer_guide":{"answer":"우리 집 마당이야.≫ 내 방 구경할래? — 앞 문장은 끝을 내려 차분하게, 뒤 문장은 묻는 말이니 끝을 올려 읽어요.","scoring_points":["마침표 뒤에 ≫ 를 했는가","설명하는 문장을 차분하게 읽는다고 했는가","묻는 문장을 끝을 올려 읽는다고 했는가"]},"explanation":["≫ 표시.","설명 문장 읽기.","묻는 문장 읽기."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L08_challenge#10','kor',1,1,'u6','L08','g1_1_kor_u6_L08_challenge','lesson_challenge','K1-1-u6-C10',4,'essay','teacher','기린을 처음 만났을 때 「나」의 마음은 어땠을지 쓰고, 그렇게 생각한 까닭을 이야기에서 찾아 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u6-C10","difficulty":4,"kind":"essay","stem":"기린을 처음 만났을 때 「나」의 마음은 어땠을지 쓰고, 그렇게 생각한 까닭을 이야기에서 찾아 말해 보세요.","answer_guide":{"answer":"예: 깜짝 놀라고 신기했을 거예요. — 「우아, 살아 있는 진짜 기린이다!」라고 느낌표를 붙여 말했으니까요.","scoring_points":["「나」의 마음을 말했는가","까닭을 이야기 속 문장에서 찾았는가","문장 부호(느낌표)를 까닭으로 들었는가"]},"explanation":["마음.","이야기에서 까닭 찾기.","부호와 마음."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_basic#1','kor',1,1,'u6','L10','g1_1_kor_u6_L10_basic','lesson_basic','K1-1-u6-C10',1,'mc','auto','대본에서 나무꾼이 산에서 만난 인물은 누구인가요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":1,"concept":"K1-1-u6-C10","difficulty":1,"kind":"mc","stem":"대본에서 나무꾼이 산에서 만난 인물은 누구인가요?","options":[{"t":"호랑이","correct":true},{"t":"곰","mis":"K1-1-u6-X14"},{"t":"토끼","mis":"K1-1-u6-X14"}],"explanation":["나무꾼은 산에서 호랑이를 만났어요.","곰이나 토끼는 대본에 나오지 않아요.","대사 앞 인물 이름을 살펴요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
