INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_basic#4','kor',1,1,'u6','L10','g1_1_kor_u6_L10_basic','lesson_basic','K1-1-u6-C10',1,'mc','auto','「뭐라고? 내가 어째서 네 형님이냐?」는 누가 한 말인가요?',ARRAY['K1-1-u6-X15']::text[],false,'{"seq":4,"concept":"K1-1-u6-C10","difficulty":1,"kind":"mc","stem":"「뭐라고? 내가 어째서 네 형님이냐?」는 누가 한 말인가요?","options":[{"t":"호랑이","correct":true},{"t":"나무꾼","mis":"K1-1-u6-X15"},{"t":"어머니","mis":"K1-1-u6-X15"}],"explanation":["셋째 대사는 호랑이가 한 말이에요.","나무꾼은 「형님」이라고 부른 쪽이고, 어머니는 대사가 없어요.","대사 앞 인물 이름을 살펴요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
