INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_basic#6','kor',1,1,'u6','L10','g1_1_kor_u6_L10_basic','lesson_basic','K1-1-u6-C9',2,'mc','auto','호랑이 대사 「아우야, 정말 반갑구나!」를 읽는 목소리로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X12','K1-1-u6-X13']::text[],false,'{"seq":6,"concept":"K1-1-u6-C9","difficulty":2,"kind":"mc","stem":"호랑이 대사 「아우야, 정말 반갑구나!」를 읽는 목소리로 알맞은 것은 어느 것인가요?","options":[{"t":"반갑고 기쁜 목소리로 힘 있게","correct":true},{"t":"작고 밋밋한 목소리로","mis":"K1-1-u6-X12"},{"t":"끝을 올려 묻는 목소리로","mis":"K1-1-u6-X13"}],"explanation":["느낌표가 있고 반가운 마음이라 기쁘게 힘 있게 읽어요.","밋밋하거나 묻듯이 읽으면 마음이 전해지지 않아요.","부호와 인물의 마음을 함께 살펴요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_basic#7','kor',1,1,'u6','L10','g1_1_kor_u6_L10_basic','lesson_basic','K1-1-u6-C8',2,'mc','auto','호랑이 대사에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],false,'{"seq":7,"concept":"K1-1-u6-C8","difficulty":2,"kind":"mc","stem":"호랑이 대사에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?","options":[{"t":"뭐라고?≫ 내가 어째서 네 형님이냐?","correct":true},{"t":"뭐라고?∨ 내가 어째서 네 형님이냐?","mis":"K1-1-u6-X11"},{"t":"뭐라고?≫ 내가 어째서 네 형∨님이냐?","mis":"K1-1-u6-X03"}],"explanation":["물음표 뒤에는 ≫(조금 더 쉬어)를 해요.","물음표 뒤에 ∨ 를 하거나 「형∨님」처럼 낱말 가운데서 끊으면 안 돼요.","부호 뒤에만 알맞은 표시를 해요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_basic#8','kor',1,1,'u6','L10','g1_1_kor_u6_L10_basic','lesson_basic','K1-1-u6-C10',2,'ox','auto','목소리 연극에서는 인물의 마음을 생각하며 대사를 읽어요.',ARRAY['K1-1-u6-X15']::text[],false,'{"seq":8,"concept":"K1-1-u6-C10","difficulty":2,"kind":"ox","stem":"목소리 연극에서는 인물의 마음을 생각하며 대사를 읽어요.","answer":"O","reason_options":[{"t":"인물이 되어 마음을 살려 읽어야 실감 나니까","correct":true},{"t":"대사만 틀리지 않으면 마음은 생각하지 않아도 되니까","mis":"K1-1-u6-X15"}],"mis":"K1-1-u6-X15","explanation":["인물의 마음을 살려 읽어야 해요.","글자만 읽으면 인물이 살아나지 않아요.","인물의 얼굴을 떠올리며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_basic#9','kor',1,1,'u6','L10','g1_1_kor_u6_L10_basic','lesson_basic','K1-1-u6-C10',2,'match','auto','대사와 그때 인물의 마음을 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u6-C10","difficulty":2,"kind":"match","stem":"대사와 그때 인물의 마음을 이으세요.","pairs":[{"l":"어흥! 마침 배가 고팠는데 잘 만났다.","r":"배가 고파 잡아먹으려는 마음"},{"l":"아이고, 형님! 이제야 만났네요!","r":"꾀를 내어 반가운 척하는 마음"},{"l":"그래? 아우야, 정말 반갑구나!","r":"아우를 만나 기쁜 마음"}],"mis":"K1-1-u6-X15","explanation":["호랑이는 처음엔 배고팠다가 나중엔 반가워했어요.","나무꾼은 꾀를 내어 반가운 척했어요.","대사마다 인물의 마음을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_basic#10','kor',1,1,'u6','L10','g1_1_kor_u6_L10_basic','lesson_basic','K1-1-u6-C9',3,'error','auto','태민이가 호랑이 대사 「아우야, 정말 반갑구나!」를 작은 목소리로 끝을 올려 읽었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#1','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C10',2,'mc','auto','나무꾼이 호랑이를 「형님」이라고 부른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":1,"concept":"K1-1-u6-C10","difficulty":2,"kind":"mc","stem":"나무꾼이 호랑이를 「형님」이라고 부른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"잡아먹히지 않으려고 꾀를 내어서","correct":true},{"t":"호랑이가 진짜 친형이라서","mis":"K1-1-u6-X14"},{"t":"호랑이에게 길을 물으려고","mis":"K1-1-u6-X14"}],"explanation":["배고픈 호랑이에게 잡아먹히지 않으려고 꾀를 냈어요.","진짜 형도 아니고, 길을 묻지도 않았어요.","호랑이의 첫 대사와 이어서 생각해요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#2','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C9',2,'mc','auto','「몇 시에 일어났니?」를 어떻게 읽으면 좋을까요?',ARRAY['K1-1-u6-X12','K1-1-u6-X13']::text[],true,'{"seq":2,"concept":"K1-1-u6-C9","difficulty":2,"kind":"mc","stem":"「몇 시에 일어났니?」를 어떻게 읽으면 좋을까요?","options":[{"t":"끝을 살짝 올려 묻듯이 읽어요","correct":true},{"t":"느낌을 살려 힘 있게 읽어요","mis":"K1-1-u6-X12"},{"t":"끝을 내려 차분하게 읽어요","mis":"K1-1-u6-X13"}],"explanation":["묻는 문장은 끝을 살짝 올려 읽어요.","끝을 내리거나 힘주어 외치면 묻는 느낌이 나지 않아요.","물음표( ? )를 보면 끝을 올려 읽어요."],"variant_rule":{"punct":{"ask":"read","mis":{"read":"X12","up":"X13"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#3','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C10',3,'mc','auto','대본에서 호랑이의 마음은 어떻게 바뀌었나요?',ARRAY['K1-1-u6-X15']::text[],false,'{"seq":3,"concept":"K1-1-u6-C10","difficulty":3,"kind":"mc","stem":"대본에서 호랑이의 마음은 어떻게 바뀌었나요?","options":[{"t":"배고픈 마음 → 놀란 마음 → 반가운 마음","correct":true},{"t":"반가운 마음 → 놀란 마음 → 배고픈 마음","mis":"K1-1-u6-X15"},{"t":"배고픈 마음 → 화난 마음 → 슬픈 마음","mis":"K1-1-u6-X15"}],"explanation":["「어흥!」(배고픔) → 「뭐라고?」(놀람) → 「반갑구나!」(반가움)예요.","차례를 뒤집거나 나오지 않은 마음을 넣으면 안 돼요.","호랑이 대사를 차례대로 읽어요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#4','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C8',3,'mc','auto','「아이고, 깜짝이야! 누가 창문을 열었어?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],true,'{"seq":4,"concept":"K1-1-u6-C8","difficulty":3,"kind":"mc","stem":"「아이고, 깜짝이야! 누가 창문을 열었어?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?","options":[{"t":"아이고,∨ 깜짝이야!≫ 누가 창문을 열었어?","correct":true},{"t":"아이고,≫ 깜짝이야!∨ 누가 창문을 열었어?","mis":"K1-1-u6-X11"},{"t":"아이고,∨ 깜짝이야!≫ 누∨가 창문을 열었어?","mis":"K1-1-u6-X03"}],"explanation":["쉼표( , ) 뒤에는 ∨(조금 쉬어), 마침표·물음표·느낌표 뒤에는 ≫(조금 더 쉬어)를 해요.","쉬는 길이를 바꾸거나 낱말 가운데서 쉬면 뜻이 잘 전해지지 않아요.","부호를 찾아 그 뒤에 알맞은 표시를 해요."],"variant_rule":{"punct":{"ask":"pause","mis":{"swap":"X11","same":"X11","split":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#5','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C10',3,'mc','auto','목소리 연극을 할 때 알맞은 모습은 어느 것인가요?',ARRAY['K1-1-u6-X15','K1-1-u6-X12']::text[],false,'{"seq":5,"concept":"K1-1-u6-C10","difficulty":3,"kind":"mc","stem":"목소리 연극을 할 때 알맞은 모습은 어느 것인가요?","options":[{"t":"내 차례를 기다렸다가 인물의 마음을 살려 대사를 읽어요","correct":true},{"t":"친구 대사까지 내가 먼저 읽어요","mis":"K1-1-u6-X15"},{"t":"대본만 보며 작은 목소리로 읽어요","mis":"K1-1-u6-X12"}],"explanation":["차례를 지키고 인물의 마음을 살려 읽어요.","남의 대사를 읽거나 밋밋하게 읽으면 연극이 살지 않아요.","내 대사 앞 이름에 동그라미 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#6','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C7',3,'error','auto','예린이가 대사를 옮겨 적었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#7','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C9',3,'ox','auto','호랑이 대사의 「어흥!」은 느낌을 살려 크고 힘차게 읽으면 좋아요.',ARRAY['K1-1-u6-X12']::text[],false,'{"seq":7,"concept":"K1-1-u6-C9","difficulty":3,"kind":"ox","stem":"호랑이 대사의 「어흥!」은 느낌을 살려 크고 힘차게 읽으면 좋아요.","answer":"O","reason_options":[{"t":"느낌표가 붙어 있어 무섭고 힘찬 느낌을 살려야 하니까","correct":true},{"t":"짧은 말이니 작게 지나가듯 읽어야 하니까","mis":"K1-1-u6-X12"}],"mis":"K1-1-u6-X12","explanation":["느낌표가 있으니 느낌을 살려 읽어요.","짧아도 느낌표 말은 힘 있게 읽어요.","인물이 되어 소리 내 봐요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#8','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C10',4,'mc','auto','나무꾼 역할을 맡았어요. 「아이고, 형님! 이제야 만났네요!」를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X13','K1-1-u6-X15']::text[],false,'{"seq":8,"concept":"K1-1-u6-C10","difficulty":4,"kind":"mc","stem":"나무꾼 역할을 맡았어요. 「아이고, 형님! 이제야 만났네요!」를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"「아이고,」 뒤에 조금 쉬고, 반가운 척하며 느낌을 살려 읽어요","correct":true},{"t":"쉬지 않고 끝을 올려 묻듯이 읽어요","mis":"K1-1-u6-X13"},{"t":"호랑이처럼 무섭게 으르렁거리며 읽어요","mis":"K1-1-u6-X15"}],"explanation":["쉼표 뒤에 조금 쉬고, 느낌표를 살려 반가운 척해요.","묻듯이 읽거나 다른 인물의 목소리로 읽으면 안 돼요.","부호·인물·마음을 모두 살펴요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#9','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C10',4,'essay','teacher','호랑이와 나무꾼 가운데 한 인물을 골라, 그 인물의 대사 하나를 어떤 목소리로 읽을지와 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u6-C10","difficulty":4,"kind":"essay","stem":"호랑이와 나무꾼 가운데 한 인물을 골라, 그 인물의 대사 하나를 어떤 목소리로 읽을지와 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 호랑이의 「어흥! 마침 배가 고팠는데 잘 만났다.」는 크고 무섭게 읽어요. — 배고파서 나무꾼을 잡아먹으려는 마음이니까요.","scoring_points":["인물과 대사를 골랐는가","어떤 목소리로 읽을지 말했는가","인물의 마음이나 문장 부호로 까닭을 말했는가"]},"explanation":["인물·대사.","목소리.","까닭."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_L10_challenge#10','kor',1,1,'u6','L10','g1_1_kor_u6_L10_challenge','lesson_challenge','K1-1-u6-C9',4,'essay','teacher','목소리 연극을 할 때 문장 부호를 잘 살펴야 하는 까닭을 두 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u6-C9","difficulty":4,"kind":"essay","stem":"목소리 연극을 할 때 문장 부호를 잘 살펴야 하는 까닭을 두 가지 써 보세요.","answer_guide":{"answer":"예: 부호에 맞게 쉬어 읽어야 뜻이 잘 전해져요. 물음표·느낌표에 맞게 목소리를 바꿔야 인물의 마음이 실감 나게 전해져요.","scoring_points":["쉬어 읽기와 관련된 까닭을 썼는가","목소리(끝 올리기·느낌 살리기)와 관련된 까닭을 썼는가","문장으로 또박또박 썼는가"]},"explanation":["쉬어 읽기.","목소리 바꾸기.","문장으로 쓰기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#1','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C1',1,'mc','auto','그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X01']::text[],false,'{"seq":1,"concept":"K1-1-u6-C1","difficulty":1,"kind":"mc","stem":"그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"자전거를 타요.","correct":true},{"t":"자전거를 가요.","mis":"K1-1-u6-X01"},{"t":"자전거를 자요.","mis":"K1-1-u6-X01"}],"explanation":["아이가 자전거를 타고 있어요.","글자 하나를 바꿔 읽으면 뜻이 달라져요.","글자 하나까지 살피며 읽어요."],"asset":{"type":"scene","icon":"🚲🧒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#2','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C2',1,'mc','auto','밤이 열리는 나무를 심는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X02','K1-1-u6-X03']::text[],false,'{"seq":2,"concept":"K1-1-u6-C2","difficulty":1,"kind":"mc","stem":"밤이 열리는 나무를 심는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"오늘 ∨ 밤나무를 심자","correct":true},{"t":"오늘 밤 ∨ 나무를 심자","mis":"K1-1-u6-X02"},{"t":"오늘 밤나 ∨ 무를 심자","mis":"K1-1-u6-X03"}],"explanation":["「밤나무」를 붙여 읽어요.","쉬는 곳이 달라지면 뜻이 달라져요.","뜻을 떠올리고 그 뜻에 맞는 곳에서 쉬어요."],"asset":{"type":"scene","icon":"🌰🌳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#3','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C3',1,'mc','auto','「강아지가 마당에서 뛰어가요.」에서 「누가(무엇이)」에 해당하는 말은 어느 것인가요?',ARRAY['K1-1-u6-X04']::text[],false,'{"seq":3,"concept":"K1-1-u6-C3","difficulty":1,"kind":"mc","stem":"「강아지가 마당에서 뛰어가요.」에서 「누가(무엇이)」에 해당하는 말은 어느 것인가요?","options":[{"t":"강아지가","correct":true},{"t":"마당에서","mis":"K1-1-u6-X04"},{"t":"뛰어가요","mis":"K1-1-u6-X04"}],"explanation":["누가(무엇이)는 「강아지가」예요.","다른 두 말은 곳·무엇을·어찌하다예요.","「~이·~가」로 끝나는 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#4','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C4',1,'mc','auto','그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":4,"concept":"K1-1-u6-C4","difficulty":1,"kind":"mc","stem":"그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"아기가 웃어요.","correct":true},{"t":"아기가 울어요.","mis":"K1-1-u6-X06"},{"t":"아기가 자요.","mis":"K1-1-u6-X06"}],"explanation":["아기가 활짝 웃고 있어요.","다른 두 문장은 그림과 하는 일이나 인물이 달라요.","누가, 무엇을 하는지 함께 살펴요."],"asset":{"type":"scene","icon":"👶😄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#5','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C6',1,'mc','auto','「?」의 이름은 무엇인가요?',ARRAY['K1-1-u6-X08']::text[],true,'{"seq":5,"concept":"K1-1-u6-C6","difficulty":1,"kind":"mc","stem":"「?」의 이름은 무엇인가요?","options":[{"t":"물음표","correct":true},{"t":"느낌표","mis":"K1-1-u6-X08"},{"t":"마침표","mis":"K1-1-u6-X08"}],"explanation":["이 부호는 물음표예요.","물음표는 묻는 문장 끝에 써요.","모양과 쓰임을 함께 떠올리며 이름을 익혀요."],"variant_rule":{"punct":{"ask":"name","mis":{"name":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#6','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C7',1,'mc','auto','다음 문장의 ◯에 알맞은 문장 부호는 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#7','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C8',1,'mc','auto','쉼표( , ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?',ARRAY['K1-1-u6-X11']::text[],false,'{"seq":7,"concept":"K1-1-u6-C8","difficulty":1,"kind":"mc","stem":"쉼표( , ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?","options":[{"t":"∨ (조금 쉬어)","correct":true},{"t":"≫ (조금 더 쉬어)","mis":"K1-1-u6-X11"},{"t":"아무 표시도 하지 않아요","mis":"K1-1-u6-X11"}],"explanation":["쉼표 뒤에는 ∨ 를 해요.","∨ 는 쉼표 뒤, ≫ 는 마침표·물음표·느낌표 뒤에 해요.","쉼표에서 하나, 끝 부호에서 둘만큼 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#8','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C10',1,'mc','auto','기린은 어디에서 나왔나요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":8,"concept":"K1-1-u6-C10","difficulty":1,"kind":"mc","stem":"기린은 어디에서 나왔나요?","options":[{"t":"해바라기 씨","correct":true},{"t":"연필꽂이","mis":"K1-1-u6-X14"},{"t":"꽃병","mis":"K1-1-u6-X14"}],"explanation":["해바라기 씨가 구르더니 기린이 되었어요.","다른 두 보기는 글에 나오지 않아요.","누가·어디서·무슨 일을 짚어요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#9','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C3',2,'mc','auto','「동생이 국수를 먹어요.」에서 「무엇을」에 해당하는 말은 어느 것인가요?',ARRAY['K1-1-u6-X04']::text[],false,'{"seq":9,"concept":"K1-1-u6-C3","difficulty":2,"kind":"mc","stem":"「동생이 국수를 먹어요.」에서 「무엇을」에 해당하는 말은 어느 것인가요?","options":[{"t":"국수를","correct":true},{"t":"동생이","mis":"K1-1-u6-X04"},{"t":"먹어요","mis":"K1-1-u6-X04"}],"explanation":["무엇을은 「국수를」이에요.","다른 두 말은 누가·어찌하다예요.","「~을·~를」로 끝나는 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#10','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C4',2,'mc','auto','놀이터 그림을 보고 답해요. 하마는 무엇을 하고 있나요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":10,"concept":"K1-1-u6-C4","difficulty":2,"kind":"mc","stem":"놀이터 그림을 보고 답해요. 하마는 무엇을 하고 있나요?","options":[{"t":"하마가 그네를 타요.","correct":true},{"t":"하마가 시소를 타요.","mis":"K1-1-u6-X06"},{"t":"하마가 모래성을 만들어요.","mis":"K1-1-u6-X06"}],"explanation":["하마는 그네를 타요.","다른 두 문장은 그림과 하는 일이나 곳이 달라요.","누가·어디서·무엇을 셋을 맞춰요."],"asset":{"type":"scene","icon":"🛝🐒🦛🐰🐿️🐻","text":"놀이터에서 원숭이는 달리고, 하마는 그네를 타요. 토끼와 다람쥐는 시소를 타고, 곰은 모래성을 다 만들었어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#11','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C5',2,'mc','auto','「우리 반 친구들은 운동장에서 축구를 해요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X07','K1-1-u6-X03']::text[],false,'{"seq":11,"concept":"K1-1-u6-C5","difficulty":2,"kind":"mc","stem":"「우리 반 친구들은 운동장에서 축구를 해요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"우리 반 친구들은 ∨ 운동장에서 축구를 해요.","correct":true},{"t":"우리 ∨ 반 ∨ 친구들은 ∨ 운동장에서 ∨ 축구를 ∨ 해요.","mis":"K1-1-u6-X07"},{"t":"우리 반 친 ∨ 구들은 운동장에서 축구를 해요.","mis":"K1-1-u6-X03"}],"explanation":["「우리 반 친구들은」 뒤에서 쉬어요.","낱말마다 끊거나 낱말 가운데서 끊으면 뜻이 끊겨요.","뜻이 이어지는 말끼리 묶어 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#12','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C6',2,'mc','auto','「와, 별이 참 많구나!」는 어떤 문장인가요?',ARRAY['K1-1-u6-X09']::text[],true,'{"seq":12,"concept":"K1-1-u6-C6","difficulty":2,"kind":"mc","stem":"「와, 별이 참 많구나!」는 어떤 문장인가요?","options":[{"t":"느낌을 나타내는 문장","correct":true},{"t":"묻는 문장","mis":"K1-1-u6-X09"},{"t":"설명하는 문장","mis":"K1-1-u6-X09"}],"explanation":["끝에 느낌표( ! )가 있는 느낌을 나타내는 문장이에요.","물음표는 묻는 문장, 느낌표는 느낌을 나타내는 문장, 마침표는 설명하는 문장 끝에 써요.","문장 끝 부호와 문장의 뜻을 함께 살펴요."],"variant_rule":{"punct":{"ask":"type","mis":{"type":"X09"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#13','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C7',2,'mc','auto','다음 문장의 ◯에 알맞은 문장 부호는 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#14','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C8',2,'mc','auto','「민지야, 이리 와. 너는 어디에 가니?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],true,'{"seq":14,"concept":"K1-1-u6-C8","difficulty":2,"kind":"mc","stem":"「민지야, 이리 와. 너는 어디에 가니?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?","options":[{"t":"민지야,∨ 이리 와.≫ 너는 어디에 가니?","correct":true},{"t":"민지야,≫ 이리 와.∨ 너는 어디에 가니?","mis":"K1-1-u6-X11"},{"t":"민지야,∨ 이리 와.≫ 너∨는 어디에 가니?","mis":"K1-1-u6-X03"}],"explanation":["쉼표( , ) 뒤에는 ∨(조금 쉬어), 마침표·물음표·느낌표 뒤에는 ≫(조금 더 쉬어)를 해요.","쉬는 길이를 바꾸거나 낱말 가운데서 쉬면 뜻이 잘 전해지지 않아요.","부호를 찾아 그 뒤에 알맞은 표시를 해요."],"variant_rule":{"punct":{"ask":"pause","mis":{"swap":"X11","same":"X11","split":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#15','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C9',2,'mc','auto','「누가 창문을 열었어?」를 어떻게 읽으면 좋을까요?',ARRAY['K1-1-u6-X12','K1-1-u6-X13']::text[],true,'{"seq":15,"concept":"K1-1-u6-C9","difficulty":2,"kind":"mc","stem":"「누가 창문을 열었어?」를 어떻게 읽으면 좋을까요?","options":[{"t":"끝을 살짝 올려 묻듯이 읽어요","correct":true},{"t":"느낌을 살려 힘 있게 읽어요","mis":"K1-1-u6-X12"},{"t":"끝을 내려 차분하게 읽어요","mis":"K1-1-u6-X13"}],"explanation":["묻는 문장은 끝을 살짝 올려 읽어요.","끝을 내리거나 힘주어 외치면 묻는 느낌이 나지 않아요.","물음표( ? )를 보면 끝을 올려 읽어요."],"variant_rule":{"punct":{"ask":"read","mis":{"read":"X12","up":"X13"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#16','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C1',2,'ox','auto','「공을 던져요.」를 「곰을 던져요.」로 읽어도 뜻은 같아요.',ARRAY['K1-1-u6-X01']::text[],false,'{"seq":16,"concept":"K1-1-u6-C1","difficulty":2,"kind":"ox","stem":"「공을 던져요.」를 「곰을 던져요.」로 읽어도 뜻은 같아요.","answer":"X","reason_options":[{"t":"「공」과 「곰」은 글자 하나 차이지만 뜻이 다르니까","correct":true},{"t":"소리가 비슷하면 뜻도 같으니까","mis":"K1-1-u6-X01"}],"mis":"K1-1-u6-X01","explanation":["「공」과 「곰」은 다른 낱말이에요.","글자 하나만 바꿔 읽어도 뜻이 달라져요.","글자를 하나씩 짚으며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
