INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#21','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C6',3,'mc','auto','물음표( ? )의 쓰임을 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u6-X08']::text[],false,'{"seq":21,"concept":"K1-1-u6-C6","difficulty":3,"kind":"mc","stem":"물음표( ? )의 쓰임을 바르게 말한 것은 어느 것인가요?","options":[{"t":"묻는 문장 끝에 써요","correct":true},{"t":"부르는 말 뒤에 써요","mis":"K1-1-u6-X08"},{"t":"설명하는 문장 끝에 써요","mis":"K1-1-u6-X08"}],"explanation":["물음표는 묻는 문장 끝에 써요.","다른 두 보기는 다른 부호의 쓰임이에요.","부호마다 쓰임을 한 번씩 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#22','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C10',3,'mc','auto','나무꾼이 호랑이를 「형님」이라고 부른 까닭은 무엇인가요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":22,"concept":"K1-1-u6-C10","difficulty":3,"kind":"mc","stem":"나무꾼이 호랑이를 「형님」이라고 부른 까닭은 무엇인가요?","options":[{"t":"잡아먹히지 않으려고 꾀를 내어서","correct":true},{"t":"호랑이가 진짜 친형이라서","mis":"K1-1-u6-X14"},{"t":"호랑이에게 길을 물으려고","mis":"K1-1-u6-X14"}],"explanation":["배고픈 호랑이에게 꾀를 냈어요.","다른 두 보기는 글과 맞지 않아요.","앞뒤 문장을 이어 까닭을 찾아요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#23','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C7',4,'mc','auto','문장 부호를 모두 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u6-X10','K1-1-u6-X09']::text[],false,'{"seq":23,"concept":"K1-1-u6-C7","difficulty":4,"kind":"mc","stem":"문장 부호를 모두 바르게 쓴 것은 어느 것인가요?","options":[{"t":"민지야, 너는 어디에 가니?","correct":true},{"t":"민지야. 너는 어디에 가니?","mis":"K1-1-u6-X10"},{"t":"민지야, 너는 어디에 가니.","mis":"K1-1-u6-X09"}],"explanation":["부르는 말 뒤 쉼표, 문장 뜻에 맞는 끝 부호를 모두 썼어요.","다른 두 보기에는 쉼표가 빠졌거나 끝 부호가 뜻과 맞지 않는 곳이 있어요.","부르는 말과 문장 끝을 하나씩 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#24','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C8',4,'mc','auto','쉬어 읽기 표시를 모두 알맞게 한 대사는 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],false,'{"seq":24,"concept":"K1-1-u6-C8","difficulty":4,"kind":"mc","stem":"쉬어 읽기 표시를 모두 알맞게 한 대사는 어느 것인가요?","options":[{"t":"아이고,∨ 형님!≫ 이제야 만났네요!","correct":true},{"t":"아이고,≫ 형님!∨ 이제야 만났네요!","mis":"K1-1-u6-X11"},{"t":"아이고,∨ 형님!≫ 이제야 만∨났네요!","mis":"K1-1-u6-X03"}],"explanation":["쉼표 뒤 ∨, 마침표·물음표·느낌표 뒤 ≫ 를 했어요.","다른 두 보기는 쉬는 길이를 바꿨거나 낱말 가운데서 끊었어요.","부호를 먼저 찾고 그 뒤에 표시해요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_a#25','kor',1,1,'u6','','g1_1_kor_u6_review_a','unit_review','K1-1-u6-C9',4,'mc','auto','「민지야, 너는 어디에 가니?」를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X13','K1-1-u6-X12']::text[],false,'{"seq":25,"concept":"K1-1-u6-C9","difficulty":4,"kind":"mc","stem":"「민지야, 너는 어디에 가니?」를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「민지야,」 뒤에 조금 쉬고 끝을 살짝 올려 읽어요","correct":true},{"t":"「민지야,」 뒤에 조금 쉬고 끝을 내려 차분하게 읽어요","mis":"K1-1-u6-X13"},{"t":"쉬지 않고 모두 같은 목소리로 읽어요","mis":"K1-1-u6-X12"}],"explanation":["부르는 말 뒤 쉼표에서 조금 쉬고, 묻는 문장이라 끝을 올려요.","끝을 반대로 하거나 밋밋하게 읽으면 뜻과 마음이 전해지지 않아요.","부호마다 쉬는 길이와 목소리를 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_b#1','kor',1,1,'u6','','g1_1_kor_u6_review_b','unit_review','K1-1-u6-C1',1,'mc','auto','그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X01']::text[],false,'{"seq":1,"concept":"K1-1-u6-C1","difficulty":1,"kind":"mc","stem":"그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"공을 차요.","correct":true},{"t":"곰을 차요.","mis":"K1-1-u6-X01"},{"t":"공을 자요.","mis":"K1-1-u6-X01"}],"explanation":["아이가 공을 차고 있어요.","글자 하나를 바꿔 읽으면 뜻이 달라져요.","글자 하나까지 살피며 읽어요."],"asset":{"type":"scene","icon":"⚽🧒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_b#2','kor',1,1,'u6','','g1_1_kor_u6_review_b','unit_review','K1-1-u6-C2',1,'mc','auto','아버지가 방으로 들어가시는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X02','K1-1-u6-X03']::text[],false,'{"seq":2,"concept":"K1-1-u6-C2","difficulty":1,"kind":"mc","stem":"아버지가 방으로 들어가시는 그림이에요. 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"아버지가 ∨ 방에 들어가신다","correct":true},{"t":"아버지 ∨ 가방에 들어가신다","mis":"K1-1-u6-X02"},{"t":"아 ∨ 버지가 방에 들어가신다","mis":"K1-1-u6-X03"}],"explanation":["「아버지가」 뒤에서 쉬어요.","쉬는 곳이 달라지면 뜻이 달라져요.","뜻을 떠올리고 그 뜻에 맞는 곳에서 쉬어요."],"asset":{"type":"scene","icon":"👨🚪"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_b#3','kor',1,1,'u6','','g1_1_kor_u6_review_b','unit_review','K1-1-u6-C3',1,'mc','auto','「아기가 침대에서 웃어요.」에서 「누가(무엇이)」에 해당하는 말은 어느 것인가요?',ARRAY['K1-1-u6-X04']::text[],false,'{"seq":3,"concept":"K1-1-u6-C3","difficulty":1,"kind":"mc","stem":"「아기가 침대에서 웃어요.」에서 「누가(무엇이)」에 해당하는 말은 어느 것인가요?","options":[{"t":"아기가","correct":true},{"t":"침대에서","mis":"K1-1-u6-X04"},{"t":"웃어요","mis":"K1-1-u6-X04"}],"explanation":["누가(무엇이)는 「아기가」예요.","다른 두 말은 곳·무엇을·어찌하다예요.","「~이·~가」로 끝나는 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_b#4','kor',1,1,'u6','','g1_1_kor_u6_review_b','unit_review','K1-1-u6-C4',1,'mc','auto','그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":4,"concept":"K1-1-u6-C4","difficulty":1,"kind":"mc","stem":"그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"새가 날아요.","correct":true},{"t":"새가 헤엄쳐요.","mis":"K1-1-u6-X06"},{"t":"물고기가 날아요.","mis":"K1-1-u6-X06"}],"explanation":["새가 하늘을 날아요.","다른 두 문장은 그림과 하는 일이나 인물이 달라요.","누가, 무엇을 하는지 함께 살펴요."],"asset":{"type":"scene","icon":"🐦☁️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_b#5','kor',1,1,'u6','','g1_1_kor_u6_review_b','unit_review','K1-1-u6-C6',1,'mc','auto','「!」의 이름은 무엇인가요?',ARRAY['K1-1-u6-X08']::text[],true,'{"seq":5,"concept":"K1-1-u6-C6","difficulty":1,"kind":"mc","stem":"「!」의 이름은 무엇인가요?","options":[{"t":"느낌표","correct":true},{"t":"물음표","mis":"K1-1-u6-X08"},{"t":"쉼표","mis":"K1-1-u6-X08"}],"explanation":["이 부호는 느낌표예요.","느낌표는 느낌을 나타내는 문장 끝에 써요.","모양과 쓰임을 함께 떠올리며 이름을 익혀요."],"variant_rule":{"punct":{"ask":"name","mis":{"name":"X08"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
