INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#7','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C8',1,'mc','auto','물음표( ? ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?',ARRAY['K1-1-u6-X11']::text[],false,'{"seq":7,"concept":"K1-1-u6-C8","difficulty":1,"kind":"mc","stem":"물음표( ? ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?","options":[{"t":"≫ (조금 더 쉬어)","correct":true},{"t":"∨ (조금 쉬어)","mis":"K1-1-u6-X11"},{"t":"아무 표시도 하지 않아요","mis":"K1-1-u6-X11"}],"explanation":["물음표 뒤에는 ≫ 를 해요.","∨ 는 쉼표 뒤, ≫ 는 마침표·물음표·느낌표 뒤에 해요.","쉼표에서 하나, 끝 부호에서 둘만큼 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#8','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C10',1,'mc','auto','기린이 들어간 곳은 어디인가요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":8,"concept":"K1-1-u6-C10","difficulty":1,"kind":"mc","stem":"기린이 들어간 곳은 어디인가요?","options":[{"t":"내 주머니","correct":true},{"t":"해바라기 꽃","mis":"K1-1-u6-X14"},{"t":"필통","mis":"K1-1-u6-X14"}],"explanation":["기린은 내 주머니에 쏙 들어갔어요.","다른 두 보기는 글에 나오지 않아요.","누가·어디서·무슨 일을 짚어요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#9','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C3',2,'mc','auto','「형이 책을 읽어요.」에서 「무엇을」에 해당하는 말은 어느 것인가요?',ARRAY['K1-1-u6-X04']::text[],false,'{"seq":9,"concept":"K1-1-u6-C3","difficulty":2,"kind":"mc","stem":"「형이 책을 읽어요.」에서 「무엇을」에 해당하는 말은 어느 것인가요?","options":[{"t":"책을","correct":true},{"t":"형이","mis":"K1-1-u6-X04"},{"t":"읽어요","mis":"K1-1-u6-X04"}],"explanation":["무엇을은 「책을」이에요.","다른 두 말은 누가·어찌하다예요.","「~을·~를」로 끝나는 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#10','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C4',2,'mc','auto','운동장에서 축구하는 그림이에요. 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":10,"concept":"K1-1-u6-C4","difficulty":2,"kind":"mc","stem":"운동장에서 축구하는 그림이에요. 알맞은 문장은 어느 것인가요?","options":[{"t":"친구들이 운동장에서 축구를 해요.","correct":true},{"t":"친구들이 교실에서 축구를 해요.","mis":"K1-1-u6-X06"},{"t":"친구들이 운동장에서 줄넘기를 해요.","mis":"K1-1-u6-X06"}],"explanation":["친구들이 운동장에서 축구를 해요.","다른 두 문장은 그림과 하는 일이나 곳이 달라요.","누가·어디서·무엇을 셋을 맞춰요."],"asset":{"type":"scene","icon":"🏫⚽🧒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#11','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C5',2,'mc','auto','「선생님께서 칠판에 글씨를 쓰세요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X07','K1-1-u6-X03']::text[],false,'{"seq":11,"concept":"K1-1-u6-C5","difficulty":2,"kind":"mc","stem":"「선생님께서 칠판에 글씨를 쓰세요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"선생님께서 ∨ 칠판에 글씨를 쓰세요.","correct":true},{"t":"선생님께서 ∨ 칠판에 ∨ 글씨를 ∨ 쓰세요.","mis":"K1-1-u6-X07"},{"t":"선생님께서 칠판에 글 ∨ 씨를 쓰세요.","mis":"K1-1-u6-X03"}],"explanation":["「선생님께서」 뒤에서 쉬어요.","낱말마다 끊거나 낱말 가운데서 끊으면 뜻이 끊겨요.","뜻이 이어지는 말끼리 묶어 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#12','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C6',2,'mc','auto','「나는 학교에 걸어가요.」는 어떤 문장인가요?',ARRAY['K1-1-u6-X09']::text[],true,'{"seq":12,"concept":"K1-1-u6-C6","difficulty":2,"kind":"mc","stem":"「나는 학교에 걸어가요.」는 어떤 문장인가요?","options":[{"t":"설명하는 문장","correct":true},{"t":"묻는 문장","mis":"K1-1-u6-X09"},{"t":"느낌을 나타내는 문장","mis":"K1-1-u6-X09"}],"explanation":["끝에 마침표( . )가 있는 설명하는 문장이에요.","물음표는 묻는 문장, 느낌표는 느낌을 나타내는 문장, 마침표는 설명하는 문장 끝에 써요.","문장 끝 부호와 문장의 뜻을 함께 살펴요."],"variant_rule":{"punct":{"ask":"type","mis":{"type":"X09"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#13','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C7',2,'mc','auto','다음 문장의 ◯에 알맞은 문장 부호는 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#14','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C8',2,'mc','auto','「누나, 이것 좀 봐. 왜 울고 있어?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],true,'{"seq":14,"concept":"K1-1-u6-C8","difficulty":2,"kind":"mc","stem":"「누나, 이것 좀 봐. 왜 울고 있어?」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?","options":[{"t":"누나,∨ 이것 좀 봐.≫ 왜 울고 있어?","correct":true},{"t":"누나,∨ 이것 좀 봐.∨ 왜 울고 있어?","mis":"K1-1-u6-X11"},{"t":"누나,∨ 이것 좀 봐.≫ 왜 울∨고 있어?","mis":"K1-1-u6-X03"}],"explanation":["쉼표( , ) 뒤에는 ∨(조금 쉬어), 마침표·물음표·느낌표 뒤에는 ≫(조금 더 쉬어)를 해요.","쉬는 길이를 바꾸거나 낱말 가운데서 쉬면 뜻이 잘 전해지지 않아요.","부호를 찾아 그 뒤에 알맞은 표시를 해요."],"variant_rule":{"punct":{"ask":"pause","mis":{"swap":"X11","same":"X11","split":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#15','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C9',2,'mc','auto','「오늘은 수요일이에요.」를 어떻게 읽으면 좋을까요?',ARRAY['K1-1-u6-X13','K1-1-u6-X12']::text[],true,'{"seq":15,"concept":"K1-1-u6-C9","difficulty":2,"kind":"mc","stem":"「오늘은 수요일이에요.」를 어떻게 읽으면 좋을까요?","options":[{"t":"끝을 내려 차분하게 읽어요","correct":true},{"t":"끝을 살짝 올려 묻듯이 읽어요","mis":"K1-1-u6-X13"},{"t":"느낌을 살려 힘 있게 읽어요","mis":"K1-1-u6-X12"}],"explanation":["설명하는 문장은 끝을 내려 차분하게 읽어요.","끝을 올리면 묻는 말처럼 들려요.","마침표( . )를 보면 차분하게 끝맺어요."],"variant_rule":{"punct":{"ask":"read","mis":{"read":"X12","up":"X13"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_c#16','kor',1,1,'u6','','g1_1_kor_u6_review_c','unit_review','K1-1-u6-C1',2,'ox','auto','「문을 열어요.」를 「물을 열어요.」로 읽어도 뜻은 같아요.',ARRAY['K1-1-u6-X01']::text[],false,'{"seq":16,"concept":"K1-1-u6-C1","difficulty":2,"kind":"ox","stem":"「문을 열어요.」를 「물을 열어요.」로 읽어도 뜻은 같아요.","answer":"X","reason_options":[{"t":"「문」과 「물」은 글자 하나 차이지만 뜻이 다르니까","correct":true},{"t":"소리가 비슷하면 뜻도 같으니까","mis":"K1-1-u6-X01"}],"mis":"K1-1-u6-X01","explanation":["「문」과 「물」은 다른 낱말이에요.","글자 하나만 바꿔 읽어도 뜻이 달라져요.","글자를 하나씩 짚으며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
