INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#7','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C8',1,'mc','auto','느낌표( ! ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?',ARRAY['K1-1-u6-X11']::text[],false,'{"seq":7,"concept":"K1-1-u6-C8","difficulty":1,"kind":"mc","stem":"느낌표( ! ) 뒤에는 어떤 쉬어 읽기 표시를 하나요?","options":[{"t":"≫ (조금 더 쉬어)","correct":true},{"t":"∨ (조금 쉬어)","mis":"K1-1-u6-X11"},{"t":"아무 표시도 하지 않아요","mis":"K1-1-u6-X11"}],"explanation":["느낌표 뒤에는 ≫ 를 해요.","∨ 는 쉼표 뒤, ≫ 는 마침표·물음표·느낌표 뒤에 해요.","쉼표에서 하나, 끝 부호에서 둘만큼 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#8','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C10',1,'mc','auto','나무꾼이 호랑이를 부른 말은 무엇인가요?',ARRAY['K1-1-u6-X14']::text[],false,'{"seq":8,"concept":"K1-1-u6-C10","difficulty":1,"kind":"mc","stem":"나무꾼이 호랑이를 부른 말은 무엇인가요?","options":[{"t":"형님","correct":true},{"t":"아우야","mis":"K1-1-u6-X14"},{"t":"할아버지","mis":"K1-1-u6-X14"}],"explanation":["나무꾼은 호랑이를 「형님」이라고 불렀어요.","다른 두 보기는 글에 나오지 않아요.","누가·어디서·무슨 일을 짚어요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥! 마침 배가 고팠는데 잘 만났다."},{"who":"나무꾼","text":"아이고, 형님! 이제야 만났네요!"},{"who":"호랑이","text":"뭐라고? 내가 어째서 네 형님이냐?"},{"who":"나무꾼","text":"어머니께서 형님이 산에서 호랑이가 되었다고 하셨어요."},{"who":"호랑이","text":"그래? 아우야, 정말 반갑구나!"},{"who":"나무꾼","text":"형님, 어머니께서 날마다 기다리세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#9','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C3',2,'mc','auto','「아빠가 설거지를 해요.」에서 「무엇을」에 해당하는 말은 어느 것인가요?',ARRAY['K1-1-u6-X04']::text[],false,'{"seq":9,"concept":"K1-1-u6-C3","difficulty":2,"kind":"mc","stem":"「아빠가 설거지를 해요.」에서 「무엇을」에 해당하는 말은 어느 것인가요?","options":[{"t":"설거지를","correct":true},{"t":"아빠가","mis":"K1-1-u6-X04"},{"t":"해요","mis":"K1-1-u6-X04"}],"explanation":["무엇을은 「설거지를」이에요.","다른 두 말은 누가·어찌하다예요.","「~을·~를」로 끝나는 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#10','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C4',2,'mc','auto','비 오는 날 그림이에요. 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u6-X06']::text[],false,'{"seq":10,"concept":"K1-1-u6-C4","difficulty":2,"kind":"mc","stem":"비 오는 날 그림이에요. 알맞은 문장은 어느 것인가요?","options":[{"t":"비가 와서 우산을 써요.","correct":true},{"t":"눈이 와서 우산을 써요.","mis":"K1-1-u6-X06"},{"t":"비가 와서 모자를 벗어요.","mis":"K1-1-u6-X06"}],"explanation":["비가 와서 우산을 써요.","다른 두 문장은 그림과 하는 일이나 곳이 달라요.","누가·어디서·무엇을 셋을 맞춰요."],"asset":{"type":"scene","icon":"🌧️☂️🧒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#11','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C5',2,'mc','auto','「키가 큰 형이 공을 높이 던졌어요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-1-u6-X07','K1-1-u6-X03']::text[],false,'{"seq":11,"concept":"K1-1-u6-C5","difficulty":2,"kind":"mc","stem":"「키가 큰 형이 공을 높이 던졌어요.」를 알맞게 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"키가 큰 형이 ∨ 공을 높이 던졌어요.","correct":true},{"t":"키가 ∨ 큰 ∨ 형이 ∨ 공을 ∨ 높이 ∨ 던졌어요.","mis":"K1-1-u6-X07"},{"t":"키가 큰 형 ∨ 이 공을 높이 던졌어요.","mis":"K1-1-u6-X03"}],"explanation":["「키가 큰 형이」 뒤에서 쉬어요.","낱말마다 끊거나 낱말 가운데서 끊으면 뜻이 끊겨요.","뜻이 이어지는 말끼리 묶어 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#12','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C6',2,'mc','auto','「어머나, 꽃이 활짝 피었구나!」는 어떤 문장인가요?',ARRAY['K1-1-u6-X09']::text[],true,'{"seq":12,"concept":"K1-1-u6-C6","difficulty":2,"kind":"mc","stem":"「어머나, 꽃이 활짝 피었구나!」는 어떤 문장인가요?","options":[{"t":"느낌을 나타내는 문장","correct":true},{"t":"묻는 문장","mis":"K1-1-u6-X09"},{"t":"설명하는 문장","mis":"K1-1-u6-X09"}],"explanation":["끝에 느낌표( ! )가 있는 느낌을 나타내는 문장이에요.","물음표는 묻는 문장, 느낌표는 느낌을 나타내는 문장, 마침표는 설명하는 문장 끝에 써요.","문장 끝 부호와 문장의 뜻을 함께 살펴요."],"variant_rule":{"punct":{"ask":"type","mis":{"type":"X09"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#13','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C7',2,'mc','auto','다음 문장의 ◯에 알맞은 문장 부호는 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#14','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C8',2,'mc','auto','「야호, 우리 반이 이겼다! 형이 공을 차요.」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],true,'{"seq":14,"concept":"K1-1-u6-C8","difficulty":2,"kind":"mc","stem":"「야호, 우리 반이 이겼다! 형이 공을 차요.」에 쉬어 읽기 표시를 알맞게 한 것은 어느 것인가요?","options":[{"t":"야호,∨ 우리 반이 이겼다!≫ 형이 공을 차요.","correct":true},{"t":"야호,≫ 우리 반이 이겼다!∨ 형이 공을 차요.","mis":"K1-1-u6-X11"},{"t":"야호,∨ 우리 반이 이겼다!≫ 형∨이 공을 차요.","mis":"K1-1-u6-X03"}],"explanation":["쉼표( , ) 뒤에는 ∨(조금 쉬어), 마침표·물음표·느낌표 뒤에는 ≫(조금 더 쉬어)를 해요.","쉬는 길이를 바꾸거나 낱말 가운데서 쉬면 뜻이 잘 전해지지 않아요.","부호를 찾아 그 뒤에 알맞은 표시를 해요."],"variant_rule":{"punct":{"ask":"pause","mis":{"swap":"X11","same":"X11","split":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#15','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C9',2,'mc','auto','「언제 우리 집에 올래?」를 어떻게 읽으면 좋을까요?',ARRAY['K1-1-u6-X12','K1-1-u6-X13']::text[],true,'{"seq":15,"concept":"K1-1-u6-C9","difficulty":2,"kind":"mc","stem":"「언제 우리 집에 올래?」를 어떻게 읽으면 좋을까요?","options":[{"t":"끝을 살짝 올려 묻듯이 읽어요","correct":true},{"t":"느낌을 살려 힘 있게 읽어요","mis":"K1-1-u6-X12"},{"t":"끝을 내려 차분하게 읽어요","mis":"K1-1-u6-X13"}],"explanation":["묻는 문장은 끝을 살짝 올려 읽어요.","끝을 내리거나 힘주어 외치면 묻는 느낌이 나지 않아요.","물음표( ? )를 보면 끝을 올려 읽어요."],"variant_rule":{"punct":{"ask":"read","mis":{"read":"X12","up":"X13"},"types":["q","ex","st"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#16','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C1',2,'ox','auto','「꿀을 먹어요.」를 「꿈을 먹어요.」로 읽어도 뜻은 같아요.',ARRAY['K1-1-u6-X01']::text[],false,'{"seq":16,"concept":"K1-1-u6-C1","difficulty":2,"kind":"ox","stem":"「꿀을 먹어요.」를 「꿈을 먹어요.」로 읽어도 뜻은 같아요.","answer":"X","reason_options":[{"t":"「꿀」과 「꿈」은 글자 하나 차이지만 뜻이 다르니까","correct":true},{"t":"소리가 비슷하면 뜻도 같으니까","mis":"K1-1-u6-X01"}],"mis":"K1-1-u6-X01","explanation":["「꿀」과 「꿈」은 다른 낱말이에요.","글자 하나만 바꿔 읽어도 뜻이 달라져요.","글자를 하나씩 짚으며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
