INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#21','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C6',3,'mc','auto','마침표( . )의 쓰임을 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u6-X08']::text[],false,'{"seq":21,"concept":"K1-1-u6-C6","difficulty":3,"kind":"mc","stem":"마침표( . )의 쓰임을 바르게 말한 것은 어느 것인가요?","options":[{"t":"설명하는 문장이 끝날 때 써요","correct":true},{"t":"부르는 말 뒤에 써요","mis":"K1-1-u6-X08"},{"t":"놀란 느낌을 나타낼 때 써요","mis":"K1-1-u6-X08"}],"explanation":["마침표는 설명하는 문장 끝에 써요.","다른 두 보기는 다른 부호의 쓰임이에요.","부호마다 쓰임을 한 번씩 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#22','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C10',3,'mc','auto','「"우아, 살아 있는 진짜 기린이다!"」라고 말할 때 「나」의 마음은 어떤가요?',ARRAY['K1-1-u6-X15']::text[],false,'{"seq":22,"concept":"K1-1-u6-C10","difficulty":3,"kind":"mc","stem":"「\"우아, 살아 있는 진짜 기린이다!\"」라고 말할 때 「나」의 마음은 어떤가요?","options":[{"t":"깜짝 놀라고 신기한 마음","correct":true},{"t":"심심하고 졸린 마음","mis":"K1-1-u6-X15"},{"t":"무섭고 슬픈 마음","mis":"K1-1-u6-X15"}],"explanation":["「우아」와 느낌표에 놀라고 신기한 마음이 담겼어요.","다른 두 보기는 글과 맞지 않아요.","앞뒤 문장을 이어 까닭을 찾아요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#23','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C7',4,'mc','auto','문장 부호를 모두 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u6-X10','K1-1-u6-X09']::text[],false,'{"seq":23,"concept":"K1-1-u6-C7","difficulty":4,"kind":"mc","stem":"문장 부호를 모두 바르게 쓴 것은 어느 것인가요?","options":[{"t":"할머니, 사과와 배를 샀어요.","correct":true},{"t":"할머니? 사과와 배를 샀어요.","mis":"K1-1-u6-X10"},{"t":"할머니, 사과와 배를 샀어요?","mis":"K1-1-u6-X09"}],"explanation":["부르는 말 뒤 쉼표, 문장 뜻에 맞는 끝 부호를 모두 썼어요.","다른 두 보기에는 쉼표가 빠졌거나 끝 부호가 뜻과 맞지 않는 곳이 있어요.","부르는 말과 문장 끝을 하나씩 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#24','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C8',4,'mc','auto','쉬어 읽기 표시를 모두 알맞게 한 대사는 어느 것인가요?',ARRAY['K1-1-u6-X11','K1-1-u6-X03']::text[],false,'{"seq":24,"concept":"K1-1-u6-C8","difficulty":4,"kind":"mc","stem":"쉬어 읽기 표시를 모두 알맞게 한 대사는 어느 것인가요?","options":[{"t":"우리 집 마당이야.≫ 내 방 구경할래?","correct":true},{"t":"우리 집 마당이야.∨ 내 방 구경할래?","mis":"K1-1-u6-X11"},{"t":"우리 집 마∨당이야.≫ 내 방 구경할래?","mis":"K1-1-u6-X03"}],"explanation":["쉼표 뒤 ∨, 마침표·물음표·느낌표 뒤 ≫ 를 했어요.","다른 두 보기는 쉬는 길이를 바꿨거나 낱말 가운데서 끊었어요.","부호를 먼저 찾고 그 뒤에 표시해요."],"asset":{"type":"passage","lines":["마당에 커다란 해바라기가 피었어요.","해바라기 씨 하나가 톡, 내 손바닥에 떨어졌어요.","씨가 데굴데굴 구르더니 아주 작은 기린이 되었어요!","\"우아, 살아 있는 진짜 기린이다!\"","기린이 목을 쭉 빼고 물었어요. \"여기는 어디야?\"","\"우리 집 마당이야. 내 방 구경할래?\"","기린은 고개를 끄덕이며 내 주머니에 쏙 들어갔어요."],"title":"해바라기 씨에서 나온 기린"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u6_review_d#25','kor',1,1,'u6','','g1_1_kor_u6_review_d','unit_review','K1-1-u6-C9',4,'mc','auto','「아이고, 깜짝이야!」를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u6-X12']::text[],false,'{"seq":25,"concept":"K1-1-u6-C9","difficulty":4,"kind":"mc","stem":"「아이고, 깜짝이야!」를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「아이고,」 뒤에 조금 쉬고 깜짝 놀란 느낌을 살려 읽어요","correct":true},{"t":"「아이고,」 뒤에 조금 쉬고 끝을 올려 묻듯이 읽어요","mis":"K1-1-u6-X12"},{"t":"쉬지 않고 졸린 목소리로 읽어요","mis":"K1-1-u6-X12"}],"explanation":["쉼표에서 조금 쉬고, 느낌표라 놀란 느낌을 살려요.","끝을 반대로 하거나 밋밋하게 읽으면 뜻과 마음이 전해지지 않아요.","부호마다 쉬는 길이와 목소리를 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
